INSERT INTO `SKYNET_tipo_questao` (`id_tipo_questao`, `tipo_nome`) VALUES (1,'Objetiva');
INSERT INTO `SKYNET_tipo_questao` (`id_tipo_questao`, `tipo_nome`) VALUES (2,'Tarefa');
