INSERT INTO `SKYNET_tipo_questao` (`id_tipo_questao`, `tipo_nome`) VALUES (4,'Desafio');
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (1,1,'As primeiras cinco fases de nossa Olimpíada acontecem por meio digital. Você está agora, provavelmente, diante de um computador... Observe estas propagandas de micro-computadores, ambas da década de 1980 3',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (2,2,'Leia o documento abaixo e selecione, dentre as alternativas, aquela que considerar a mais pertinente. Sobre os excertos da carta de Pero Vaz de Caminha acima, podemos dizer:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (3,3,'A carta de Pero Vaz de Caminha foi recuperada pela historiografia nacional principalmente durante o século XIX. Foi re-editada e tornou-se de grande interesse, considerada a “certidão de nascimento” do Brasil. Ela pôde ser assim chamada porque:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (4,4,'A imagem que vemos acima:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (5,5,'Imagens como a abaixo, cujo interior é oco, foram comuns na região das Minas Gerais durante o século XVIII. Sobre ela podemos dizer que:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (6,6,'Estes dois mapas, um de 1822 e outro atual, registram momentos históricos distintos da conformação do território nacional. Ao observar os dois mapas, pode-se afirmar que:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (7,7,'Neste trecho do romance de Lima Barreto, publicado na forma de folhetim em 1911 no Jornal do Commercio, e depois editado em 1915, temos:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (8,8,'Observe o documento e indique a alternativa mais pertinente:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (9,9,'A imagem abaixo expressa de forma irônica uma fase da história recente do Brasil:',1,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (10,10,'Nessa tarefa, vamos produzir um documento a respeito das pessoas que estão participando da Olimpíada.',1,2);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (11,11,'Sobre esta fotografia abaixo do bando de Lampião, feita a pedido do governador João Bezerra, pode-se afirmar:',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (12,12,'\"Após ler os dois textos acima, selecione a alternativa:\" (Análise dos costumes e vida cotidiana no Brasil, 1819-1823)',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (13,13,'A imagem abaixo, sobre o fim da Guerra do Paraguai, foi publicada na revista Semana Illustrada de 27 março 1870. A partir da observação da imagem e de sua legenda podemos dizer que:',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (14,14,'Jean de Walbeeck, no Relatório apresentado ao parlamento holandês em 1633, ao discorrer sobre a possibilidade de invasão de terras brasileiras, apontou: Baseado nos seus conhecimentos e nas informações contidas no documento acima, escolha a alternativa:',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (15,15,'Observando o texto de João do Rio e a imagem e o slogan da propaganda, podemos afirmar:',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (16,16,'(Implícito: Analisar o contexto do romance e suas referências à punição naval)',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (17,17,'Leia o documento abaixo atentamente e observe os mapas que elaboramos para esta questão, procurando localizar as colônias que o texto cita. É pertinente afirmar que:',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (18,18,'A partir do documento e dos seus conhecimentos, podemos afirmar que:',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (19,19,'(Implícito: Análise da mobilização e do contexto do voto feminino no Brasil)',2,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (20,20,'Selecionar o seculo correto de cada documento',2,2);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (21,21,'O diálogo acima teria se passado na década de 1550 entre um tupinambá, do grupo nativo da costa brasileira, e o pastor calvinista Jean de Léry(1534-1611). O indígena queria saber por que os europeus vinham de terras longínquas a fim de buscar madeira para a extração de tintas.',3,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (22,22,'Em 1o de junho de 1826, o navio Frederico partiu do porto de Bremen, na atual Alemanha, com destino ao Brasil. Um documento de registro mostra que os colonos transportados nesta embarcação eram os seguintes: Observando essa lista e as informações nela contidas, podemos afirmar:',3,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (23,23,'\"Escolha a alternativa mais pertinente:\" (Análise do contexto social e político da Conjuração Baiana)',3,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (24,24,'\"Assinale:\" (Análise do nacionalismo e simbologia do Integralismo)',3,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (25,25,'\"O documento acima:\" (Descrever a mineração e migrações no início do século XVIII)',3,1);
