INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (267,1,'Entre os dias 28 de dezembro de 1879 e 4 de janeiro de 1880 a capital do Império foi tomada por uma série de manifestações públicas que ficaram conhecidas como Revolta do Vintém ou Motim do Vintém. Tais manifestações tinham como foco principal protestar contra a cobrança da taxa de um vintém (moeda de cobre cujo valor correspondia a 20 réis) sobre as passagens de bondes que circulavam na cidade do Rio de Janeiro e que entraria em vigor a partir do di1a 12o de janeiro de 1880. Em sua Revista Illustrada, Ângelo Agostini motivado pela “(...) ansiedade de nossos leitores em vêr produzidos os principais e extraordinários acontecimentos (...)”, publicou um suplemento à edição 189 do semanário. Sobre o documento podemos dizer que:',21,1);
