INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (439,35,'Em junho de 2016, as redes sociais foram palco da \"Guerra dos Memes\" entre Brasil e Portugal: a conta no Twitter \"In Portugal We Don\'t\" (Em Portugal nós não...) começou a fazer sucesso depois de usar como inspiração, em seus tweets, um dos memes brasileiros de maior sucesso no ano anterior: A partir dos memes destacados e do tipo de humor que mobilizam, escolha uma alternativa:',36,1);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (440,36,'Fundada em 1892 na atual cidade de João Pessoa, na Paraíba, a Fábrica de Vinho Tito Silva foi uma das mais importantes fábricas de vinho de caju do Brasil. Na década de 1970, a fábrica foi descoberta pelo Centro Nacional de Referência Cultural (CNRC), em um estudo que visava mapear a importância do caju na sociedade brasileira, e em 1984, foi tombada pelo Instituto do Patrimônio Histórico e Artístico Nacional (IPHAN). Veja algumas fotografias do local realizadas pelo IPHAN e, em seguida, selecione a alternativa mais adequada.',36,1);
