INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (782,46,'Trata-se de uma tarefa que traz uma atividade bastante comum aos historiadores: ler, decifrar e compreender documentos produzidos no passado. Nesta Tarefa trazemos para vocês uma carta do início do século XX, e os desafiamos a ler, entender e transcrever esse documento.',77,2);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (783,47,'A Tarefa consiste em produzir um catálogo de objetos do espaço doméstico, onde cada equipe vai contribuir com seis páginas. A equipe deve: 1) selecionar dois objetos antigos do ambiente doméstico; 2) fotografá-los em fundo neutro; 3) descrevê-los (nome, ano, material, origem); 4) explicar seus usos no passado e presente; 5) produzir um texto de reflexão sobre a relevância histórica desses objetos.',78,3);
