INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (830,46,'Prezado(a)s participantes da 17a Olimpíada Nacional em História do Brasil Apresentamos aqui a quarta Tarefa da Olimpíada. Trata-se de uma tarefa criada na 10a edição da ONHB e que traz uma atividade bastante comum aos historiadores. Quando os historiadores fazem suas pesquisas, por exemplo, em arquivos, bibliotecas, museus e acervos pessoais, frequentemente têm que ler, decifrar e compreender documentos produzidos no passado. Nesta Tarefa trazemos para vocês um relatório do fim do século XIX, e os desafiamos a ler, entender e transcrever esse documento. Como ele está em letra cursiva (escrita à mão), vocês devem seguir algumas dicas que os pesquisadores utilizam: a) leiam com calma cada palavra, tentando dar sentido ao que está escrito; b) procurem se acostumar com as formas como o(s) autor(s) desenha(m) certas letras, pois essas formas se repetem e podem auxiliar a decifrar outras palavras; c) estejam atentos aos detalhes - o historiador também é uma espécie de “detetive do passado”.',83,2);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (831,47,'Escolha um meio de comunicação de massa (1900-1960) e produza dois textos acadêmicos comparativos.',84,3);
INSERT INTO `SKYNET_questao` (`id_questao`, `num_questao`, `enunciado`, `id_fase_id`, `id_tipo_questao_id`) VALUES (832,48,'TAREFA: DADOS INEXISTENTES',85,4);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (1,1,'A','As propagandas indicam que o computador tornava-se um equipamento pessoal, utilizado nos lares.',1);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2,4,'B','A propaganda do TK95 apela para a questão da informação, tanto em seu texto como na imagem, demonstrando outros usos potenciais para aquela máquina.',1);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (3,0,'C','O TK 85 era um equipamento pouco sofisticado, o que tornava extremamente lento para o usuário comum navegar na internet.',1);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (4,5,'D','À medida que havia mais recursos tecnológicos, o computador se tornava mais presente na vida das pessoas, deixando de ser um equipamento prioritariamente de trabalho, trazendo recursos de lazer.',1);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (5,1,'A','Na carta ao rei de Portugal Pero Vaz de Caminha descreve a terra encontrada.',2);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (6,4,'B','O documento descreve uma população nativa que o autor narra como generosa e gentil, e por este motivo deve ser cuidada.',2);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (7,5,'C','A carta indica ao rei de Portugal formas de se apossar de riquezas e de expandir o cristianismo.',2);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (8,0,'D','A carta indica que os índios produziam seus alimentos em roças e criavam rebanhos para seu sustento.',2);
