INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (14,0,'B','É um plano urbano cujos prédios, ainda em sua estrutura, abrigariam moradias populares.',4);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (15,5,'C','É um documento que registra a construção da capital do Brasil.',4);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (16,4,'D','Mostra a construção de uma cidade planejada.',4);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (17,1,'A','Se trata de uma estátua feita em madeira, provavelmente por algum artista da região das minas.',5);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (18,4,'B','Era utilizada para o contrabando de ouro, driblando a fiscalização colonial.',5);
