INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (36,4,'D','A figura central da charge representa os poderes dominantes do Brasil naquela época.',9);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (37,4,'A','o governo de Getúlio Vargas (1930-1945) empenhou-se em registrar o bando de Lampião derrotado e degolado.',11);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (38,0,'B','o bando de Lampião não se enquadra na noção de banditismo social, proposta por Eric Hobsbawm.',11);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (39,5,'C','a fotografia, que exibe as cabeças dos cangaceiros e os chapéus e outros objetos adornados, foi encomendada pelo governo baiano e de Getúlio Vargas.',11);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (40,1,'D','o cangaço é um grande tema literário e audiovisual no Brasil do século XX.',11);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (41,1,'A','os dois textos se referem a um conjunto diversificado de hábitos de alimentação em diferentes regiões do Brasil nas primeiras décadas do século XIX.',12);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (42,4,'B','os textos dos viajantes estrangeiros nos informam como viviam nossos antepassados e os costumes característicos desta época.',12);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (43,5,'C','a vida cotidiana em partes distintas do Brasil indica as diferenças de economia, sociedade e cultura entre as vilas rurais do interior e os padrões burgueses europeizados.',12);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (44,0,'D','os viajantes estrangeiros estavam mais interessados na economia brasileira do que em mostrar costumes nacionais.',12);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (45,1,'A','a morte de Solano Lopez foi descrita como um grande feito brasileiro.',13);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (46,0,'B','o autor via como diabólica a participação brasileira na guerra.',13);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (47,4,'C','para o autor a guerra do Paraguai foi uma batalha contra a tirania de um governante cruel.',13);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (48,5,'D','a descrição do líder paraguaio como um monstro ajudou a construir a imagem do Brasil como o de libertador daquela nação.',13);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (49,4,'A','o documento refere-se à justificativa para a invasão holandesa no Brasil.',14);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (50,1,'B','o documento indica interesse comercial holandês pelo Brasil.',14);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (51,0,'C','a região setentrional à qual o documento se refere é a atual região Norte do país.',14);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (52,5,'D','além do açúcar, havia vários interesses marítimo-comerciais dos holandeses incluindo a desmontagem do domínio português.',14);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (53,4,'A','o texto e a imagem tratam dos impactos gerados pelo automóvel. A crônica de João do Rio descreve o contraste entre um equipamento moderno e uma cidade antiga.',15);
