INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (242,4,'B','as falas expressam adjetivos que se referem à aparência e à jovialidade do Presidente Fernando Collor de Mello.',65);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (243,1,'C','a maior parte das falas aborda a aparência física do presidente e, no plano do marketing político, relaciona a capacidade administrativa à juventude e à beleza.',65);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (244,5,'D','Collor e Ulysses Guimarães haviam sido aliados na época das Diretas-Já.',65);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (245,4,'A','a fotografia é uma referência ao lema integralista “Deus, Pátria e Família.”',66);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (246,0,'B','a Ação Integralista Brasileira foi fundada por fascistas italianos no Brasil.',66);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (247,5,'C','na imagem, a “família integralista” se sobrepõe à família definida pelos laços de sangue.',66);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (248,1,'D','à exceção da noiva, o tema central da foto é masculino e integralista.',66);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (249,5,'A','utiliza dados reais sobre o analfabetismo para construir uma metáfora sobre a distância entre a idéia de cidadania e seu exercício efetivo.',67);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (250,0,'B','critica a Constituição Brasileira que não dá acesso a todos os indivíduos da nação.',67);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (251,1,'C','demonstra que a grande maioria da população brasileira era analfabeta em 1876.',67);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (252,4,'D','no trecho “Votam como vão à festa da Penha, - por divertimento” faz uma crítica à participação política da população brasileira do período.',67);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (253,1,'A','segundo a autora francesa as principais características das brasileiras são a necessidade de demonstrar que mandam e a vergonha de mostrar que trabalham.',68);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (254,4,'B','o documento possibilita a compreensão de parte da vida cotidiana do inicio do século XIX, já que nos permite visualizar a organização de uma rede de relações de trabalho.',68);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (255,0,'C','o texto indica que os ganhos obtidos pelos escravos na cidade eram insignificantes.',68);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (256,5,'D','é uma descrição movida pelo estranhamento que o olhar estrangeiro tem ante a organização do trabalho e a vida doméstica no Rio de Janeiro do século XIX.',68);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (257,1,'A','o excerto traça um histórico da vida de Getúlio Vargas, que ingressou no cenário político nacional após a Revolução de 1930.',69);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (258,4,'B','o autor critica o caráter pragmático da política adotada por Vargas.',69);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (259,5,'C','segundo o excerto, o suicídio encobre num manto de esquecimento as contradições dos atos políticos praticados por Getúlio.',69);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (260,0,'D','segundo o autor, Getúlio fora fiel ao State democrático de direito, chegando mesmo à prática do suicídio como forma de protesto e de defesa de tais ideais.',69);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (261,0,'A','retratar indígenas do Brasil era proibido pelo governo português e pela Igreja durante o século XVI, por isso o artista do quadro O inferno preferiu não se identificar ou assinar a obra.',71);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (262,5,'B','as duas imagens expressam pontos de vista diferentes sobre os indígenas na América portuguesa, mas, em ambas, há um ponto comum: os ameríndios aparecem estilizados, em contextos cristãos e retratados do ponto de vista do europeu.',71);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (263,4,'C','no quadro Adoração dos magos, o indígena que substitui um dos reis magos, pode ser interpretado como a possibilidade de integração dos nativos à fé e à tradição cristãs.',71);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (264,1,'D','no quadro O inferno, atributos indígenas no demônio, como o cocar, podem ser interpretados como uma associação entre a imagem dos índios e o mal.',71);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (265,1,'A','os museus têm um caráter pedagógico que podem torná-los um importante auxílio no ensino de modo geral.',72);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (266,5,'B','há uma clara diferença entre constituir acervos e coleções e comunicar esse acervo por meio de exposições para o público.',72);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (267,4,'C','realizar processos de seleção e articular idéias em detrimento de outras faz parte do modo de funcionamento dos museus.',72);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (268,0,'D','o texto defende que temas como nacionalismo, regionalismo e elementos da natureza não são temas pertinentes à prática do museu.',72);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (269,4,'A','foi um movimento permeado pelas idéias iluministas que contestava o poder absoluto do rei.',73);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (270,1,'B','estabelecia o fim da Monarquia como caminho para a liberdade.',73);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (271,0,'C','afirmava o despotismo e a tirania do sistema monárquico, apontando a democracia plena e universal como alternativa desejável.',73);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (272,5,'D','negava a divindade do Rei ao afirmar que o mesmo fora criado pelo povo.',73);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (273,4,'A','os diferentes processos históricos vividos na região amazônica podem ser observados a partir de suas práticas culinárias.',74);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (274,1,'B','os índios, os negros, as migrações internas e externas contribuíram para a formação da culinária amazônica ao longo de séculos.',74);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (275,0,'C','o fato de os alimentos virem de diferentes origens prova que aquela região não tem uma cultura culinária própria.',74);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (276,5,'D','a especificidade culinária da região amazônica sintetiza em si grandes marcos de exploração e expansão do território brasileiro.',74);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (277,1,'A','Ângelo Agostini critica não apenas a postura do líder do Partido Liberal, como também os fazendeiros por ele representados.',75);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (278,0,'B','a frase “escravidão ou morte” demonstra como a sociedade brasileira do século XIX não poderia sobreviver sem o trabalho dos escravos.',75);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (279,5,'C','ao comparar o “projecto de uma estátua equestre para o illustre chefe do partido liberal” àquela de Pedro I, o autor atrela a ideia de independência à de abolição.',75);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (280,4,'D','retrata a luta dos senhores de escravos para a manutenção da escravidão representando-os como cruéis.',75);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (281,4,'A','o texto do jornal cristaliza uma interpretação histórica do Brasil.',76);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (282,1,'B','o documento retrata a valorização de um mito nacional, Tiradentes, que se enraizou no imaginário brasileiro como um símbolo de luta pela liberdade pátria.',76);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (283,5,'C','a identificação de Silvério dos Reis como sendo um “não brasileiro” constrói uma perspectiva histórica de nacionalismo ausente no momento da Inconfidência Mineira, mas em discussão no período em que o texto foi escrito.',76);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (284,0,'D','o Diário de Minas define Tiradentes como um herói nacional ao estabelecer uma linearidade histórica entre a Inconfidência Mineira e a Proclamação da República.',76);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (285,1,'A','Frei Vicente do Salvador nos mostra no nome “Brasil” a característica demoníaca do lugar.',77);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (286,5,'B','o esforço do autor é reafirmar os objetivos da colonização portuguesa: o desbravamento, a ocupação de terras brasileiras e as premissas cristãs.',77);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (287,4,'C','Frei Vicente reforça sua argumentação ao citar a experiência de um bispo em terras brasileiras, que percebe problemas da colonização na ausência de um interesse comum.',77);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (288,0,'D','por estar preocupado com a questão religiosa na colônia, a problemática central do frei é investigar a origem do nome “Brasil”.',77);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (289,1,'A','as imagens do “Cigarro Fascista” e da “Civilização” representam formas de propagandear ideologias diversas.',78);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (290,5,'B','as imagens representam a diversidade política presente na imprensa brasileira comercial e operária da década de 1920, remetendo a ideologias contraditórias e concomitantes como o fascismo e o anarquismo.',78);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (291,0,'C','o anarquismo foi a principal ideologia presente nos movimento operários das décadas de 1910 e 1920, na cidade de São Paulo.',78);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (292,4,'D','a propaganda do cigarro apresenta como o ideário fascista também estava presente no universo político da década de 1920. Algumas associações são representativas desse ideário, como a “Società Dopo Lavoro” e a “Liga Operária Católica”, introduzida no Brasil em 1902.',78);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (293,4,'A','os relatos se constituem numa fonte de pesquisa que faz referência a um momento da imigração italiana, caracterizada pela contratação de mão-de-obra estrangeira para a lavoura do café e do posterior processo de migração e de crescimento urbano de São Paulo.',79);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (294,1,'B','as lembranças descrevem a vida familiar, a escola, o trabalho, as atividades urbanas, e todas passam a fazer parte do relato de vida do entrevistado.',79);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (295,5,'C','os depoimentos dos entrevistados são um trabalho de elaboração do passado, realizado por meio de um esforço de compreensão e de esclarecimento a partir do presente.',79);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (296,0,'D','as memórias pessoais são fontes que não podem ser utilizadas por historiadores, por serem documentos parciais.',79);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (297,0,'A','o ex-ministro das Relações Exteriores, Magalhães Pinto, apóia uma maior centralização do poder nas mãos do presidente da república como forma de contornar o contexto de caos em que o país estava mergulhado.',81);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (298,4,'B','o contexto em que a reunião do Conselho de Segurança Nacional ocorreu fora caracterizado por movimentos de agitação e oposição ao regime militar, sendo exemplo disso o discurso do então deputado federal Márcio Moreira Alves, proferido em 1968.',81);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (299,5,'C','na argumentação de Magalhães Pinto, a ditadura apresentava-se como necessária e incontornável e o general Arthur Costa e Silva, como vítima desse processo.',81);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (300,0,'D','a fala do ministro evidencia que desde o início havia um plano de endurecimento do regime político previsto pelos militares, como foi feito com o fechamento do Congresso Nacional.',81);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (301,0,'A','em ambos os casos fica explicita a idéia que o brasileiro é de natureza malandra.',82);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (302,1,'B','nos sambas, há uma caracterização nítida do malandro, que envolve suas roupas, seus sapatos, hábitos e relação com a música.',82);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (303,5,'C','o malandro descrito por Wilson Batista critica a idéia do enriquecimento e ascensão pelo trabalho; o malandro descrito por Noel Rosa tampouco se dedica ao trabalho (rapaz folgado) mas se afasta da violência.',82);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (304,4,'D','no período, o samba se mostrava cada vez mais uma mercadoria valiosa e sua produção e divulgação era fiscalizada pelo Departamento de Imprensa e Propaganda.',82);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (305,1,'A','os dois textos trazem idéias relacionadas à ação do Partido Comunista, no final da década de 1940.',83);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (306,0,'B','dada a formação religiosa de grande parte da classe trabalhadora brasileira, o Partido Comunista Brasileiro propunha sensibilizar o proletariado a partir de convicções religiosas, para daí alcançar seus objetivos revolucionários.',83);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (307,4,'C','o Partido Comunista Brasileiro estava alinhado às diretrizes do Partido Comunista Soviético, que naquele contexto avançava seu domínio no Leste Europeu.',83);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (308,5,'D','o depoimento do trabalhador-militante comunista aborda um modo possível de levar a idéia de mobilização aos seus colegas de trabalho, tendo em vista a ilegalidade do partido e a dificuldade de organizar o movimento no interior do país.',83);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (309,4,'A','a imigração árabe, mais especificamente a sírio-libanesa, teve como destino as grandes capitais brasileiras no início do séc. XX, que estavam sofrendo um processo de transformação urbana e ampliação, por exemplo, de mercados e serviços, caracterizados pelo mascate e pelas “lojinhas”.',84);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (310,1,'B','os documentos retratam, de diferentes maneiras, a presença do imigrante árabe na sociedade brasileira e sua influência sobre a cultura.',84);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (311,5,'C','dentre as razões para a imigração de árabes e sírio-libaneses está a desagregação do império Turco-Otomano – uma das razões para serem chamados de turcos – e o fato de poderem atuar, no Brasil, em setores como o comércio de artigos e produtos manufaturados.',84);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (312,0,'D','a razão que levou os imigrantes sírio-libaneses a atuarem em atividades econômicas vinculadas ao comércio e às cidades foi a inadaptação dessas comunidades ao trabalho no campo.',84);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (313,4,'A','o lento desaparecimento da cultura de cana no Brasil trouxe o fim dos engenhos.',85);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (314,1,'B','trata-se de uma narrativa que descreve o Brasil pós-1930, a crise do setor agroexportador da cana de açúcar e a reorientação do eixo econômico para a indústria.',85);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (315,5,'C','a narrativa descreve a fragilidade econômica do engenho e o desgaste de seu senhor.',85);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (316,0,'D','apresenta metaforicamente mudanças tecnológicas e das relações de trabalho e de poder no Nordeste brasileiro pós-1930.',85);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (317,0,'A','o declínio na construção de novos conventos no Brasil possibilitou o aumento de casamentos no Brasil colonial.',86);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (318,5,'B','as opções de casamento eram restritas pela distribuição desigual de homens e mulheres pelo território colonial bem como por questões de dote e estatutos de pureza de sangue.',86);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (319,4,'C','a situação de falta de mulheres na colônia levou à promulgação de um alvará régio em 1732 proibindo a saída de mulheres do Brasil para Portugal.',86);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (320,1,'D','o documento opõe a vida religiosa à vida conjugal, optando pela segunda como mantenedora da povoação das terras brasileiras.',86);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (321,4,'A','a presença da arquitetura jesuítica do século XVII.',87);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (322,1,'B','o grande movimento de pessoas e a ocupação dos espaços torna difícil visualizar o conjunto arquitetônico tombado.',87);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (323,0,'C','o tombamento de um patrimônio cultural é suficiente para garantir a sua preservação.',87);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (324,5,'D','a coexistência do bem cultural com a atividade comercial viabiliza indiretamente o reconhecimento do patrimônio cultural.',87);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (325,1,'A','até o meio do século passado, arqueólogos aceitavam a hipótese de que a América teria sido povoada há mais ou menos 12 mil anos, a partir da migração de povos oriundos da Ásia.',88);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (326,4,'B','a simultaneidade do povoamento no norte e no sul do continente, pressuposta pela datação do carbono 14, em Lagoa Santa, enfraquece a hipótese de um foco único de origem do Homem Americano.',88);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (327,0,'C','as pesquisas arqueológicas realizadas no Brasil não contribuem para a compreensão do povoamento da América, já que os achados brasileiros são contemporâneos aos encontrados nos planaltos da América do Norte.',88);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (328,5,'D','quanto mais distantes os eventos históricos, menos precisas são as informações e maior a necessidade de recorrer a abordagens interdisciplinares para interpretá-los.',88);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (329,0,'A','no documento de 1925 estão presentes as mesmas justificativas difundidas para a transferência da capital para o Planalto Central, 32 anos mais tarde, com a construção de Brasília.',89);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (330,5,'B','no primeiro documento fica implícito o contexto histórico marcado pelos movimentos tenentistas e as reivindicações da classe trabalhadora.',89);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (331,4,'C','no contexto histórico de 1925, o presidente entende que a capital deveria ser construída em um lugar neutro em relação às reivindicações de classes e sob a luz do exemplo norte-americano.',89);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (332,1,'D','a argumentação de JK enfatiza a necessidade de integração nacional e faz referência aos textos constitucionais que já previam a transferência da capital federal desde a primeira constituição da República.',89);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (333,1,'A','o texto escrito pelo advogado soteropolitano Edison Carneiro, estudioso dos cultos religiosos africanos no Brasil, durante os anos 1940, apresenta os quilombos como uma reação negativa e simples do homem negro à escravidão.',90);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (334,0,'B','os textos de Edison Carneiro, Zezito Araújo e Rappin Hood atestam o interesse histórico e social acerca do Quilombo de Palmares. Desde o século XVII até a atualidade, Palmares tem sido objeto de discussão, admiração e exaltação por parte da historiografia e da sociedade como um todo.',90);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (335,5,'C','para Rappin Hood, Zumbi seria um símbolo da luta contemporânea dos negros. De forma anacrônica, o rapper projeta um conceito atual, o de cidadania, para o contexto do Brasil do século XVII.',90);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (336,4,'D','as palavras do historiador Zezito Araújo, escritas em um contexto temporal diferente do vivenciado por Edison Carneiro, exaltam a experiência social do Quilombo de Palmares que teria permitido a convivência de índios, negros, brancos e gentis. Ao contrário de Carneiro, a excepcionalidade de Palmares não se encontra na força bélica deste quilombo.',90);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (337,4,'A','a idéia de “moldar sua própria história” se refere à autonomia dos povos indígenas quanto ao contato com o homem branco, longe de serem tratados apenas como vítimas do processo.',91);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (338,5,'B','os mitos servem ao conhecimento da história de cada grupo indígena, contada pelos próprios sujeitos do processo, de modo que não existe uma história unívoca do contato entre índios e outros.',91);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (339,1,'C','os textos abordam a situação de contato narrada pelos povos indígenas por meio da reelaboração dos seus mitos.',91);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (340,0,'D','os mitos são relatos fixos sobre as origens dos povos indígenas e narram o contato inicial com os europeus desde sua chegada.',91);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (341,1,'A','trata-se de uma referência a epidemia de febre-amarela na cidade do Rio de Janeiro, em 1876.',92);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (342,0,'B','a charge mostra o ministro agradecendo à morte, pois a atuação dela permite combater o problema da febre amarela.',92);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (343,5,'C','por meio do diálogo entre a Febre e o Ministro do Império o autor faz uma crítica às políticas públicas de combate à doença e aos órgãos por ela responsáveis.',92);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (344,4,'D','aponta para números assustadores de mortos, mais de 80 por dia, demonstrando que as epidemias eram um sério problema para a população e o governo Imperial.',92);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (345,1,'A','inicia descrevendo uma manifestação popular que começa nas ruas e que se encaminha para a Casa da Câmara, onde se reuniam os governantes locais.',93);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (346,5,'B','conclui que, apesar do lema “carne sem osso e farinha sem caroço”, o preço dos alimentos não é razão suficiente para explicar o motim.',93);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (347,0,'C','considera corriqueiros os ataques ocorridos violentos contra a Câmara e contra a população.',93);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (348,4,'D','apresenta vários argumentos que tornam um acontecimento aparentemente pontual em um acontecimento de significado mais amplo.',93);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (349,1,'A','trata de um movimento ocorrido na Bahia em contestação a carestia dos gêneros alimentícios, especialmente da farinha de mandioca principal fonte de alimento dos mais pobres, que culminou em violência sendo reprimido pelo governo e pela guarda nacional.',94);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (350,0,'B','o protesto contra as freiras francesas e contra a carestia de preços serviram são manifestações cotidianas que não se associam a tensões já existentes entre a Câmara e o Presidente da Província.',94);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (351,5,'C','o movimento “Carne sem osso e farinha sem caroço” deve ser inserido em um grupo de movimentos que apontam para uma cultura política de protesto contra estrangeiros e de afirmação nacional recorrente na Bahia desde o período colonial.',94);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (352,4,'D','ao emprestarem ao protesto gestos rituais, como acercarem-se da Câmara e tocar o sino, os manifestantes acabavam por legitimar o movimento, na medida em que esses gestos remetiam a outros momentos em que a busca por direitos havia sido levantada.',94);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (353,1,'A','a parede de taipa, as bases estruturais de madeira e o chão de terra batida representam o ambiente rústico de morada desse caipira no que se refere à técnica de construção utilizada.',95);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (354,5,'B','o caipira conforme ali representado transformou-se numa espécie de símbolo do homem simples do interior.',95);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (355,4,'C','o quadro nos sugere dois olhares possíveis sobre a vida caipira, ora compreendida sob a perspectiva do atraso interiorano, ora valorizada pela leveza e simplicidade.',95);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (356,0,'D','o caipira mostrado pelo artista em 1893 ainda é constantemente encontrado em regiões distantes do interior do país.',95);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (357,0,'A','a carta de Caminha perde importância histórica quando comparada aos documentos produzidos por Américo Vespúcio.',96);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (358,4,'B','no início do século XVI, aparecem textos inaugurais sobre a nomeação e o conhecimento do Novo Mundo.',96);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (359,5,'C','a versão oficial da história do Brasil que estabelece a viagem de Pedro Álvares Cabral como a mais importante implica o apagamento de outras expedições.',96);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (360,1,'D','as cartas de Américo Vespúcio tornam o empreendimento português de interesse na Europa.',96);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (361,1,'A','o autor do relato tinha como público leitor pessoas que desconheciam as práticas cotidianas do catolicismo no Brasil da primeira metade do século XIX.',97);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (362,4,'B','pela descrição podemos afirmar que algumas práticas cotidianas do catolicismo nivelavam os grupos sociais e não levava em conta a hierarquia clerical.',97);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (363,0,'C','tal como apresentado no relato, os negros eram obrigados a seguir práticas religiosas diversas das suas práticas originais.',97);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (364,5,'D','muitas das práticas devocionais daquele tempo ainda fazem parte da cultura religiosa do Brasil atual',97);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (365,5,'A','a região do Pantanal foi descrita pelos conquistadores europeus, sobretudo espanhóis, entre os séculos XVI e XVII, como dotada de uma geografia mágica, na realidade desconhecida pelos europeus.',98);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (366,4,'B','trata-se de uma descrição feita por um autor europeu que estabelece uma analogia entre o “mar” conhecido por eles e os rios em cheia.',98);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (367,1,'C','no texto, o narrador do século XVI aponta a relação entre a sazonalidade na natureza que marca o ritmo da vida nas terras inundáveis do atual Pantanal, com a vida cotidiana dos seus habitantes, os naturais do rio.',98);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (368,0,'D','a região descrita foi incorporada ao território nacional no final do século XIX, quando se consolidou a expansão para o Oeste.',98);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (369,4,'A','afirma o despreparo do exército brasileiro frente à Guerra do Paraguai.',99);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (370,1,'B','reforça a figura de D. Pedro II como um imperador pacífico e ordenador.',99);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (371,5,'C','propõe a interpretação que retira qualquer responsabilidade do Brasil pela Guerra do Paraguai ou os excessos porventura cometidos.',99);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (372,0,'D','elogia a insubmissão das classes militares à figura do Imperador.',99);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (373,1,'A','trata da revogação da carta de liberdade – com condição de servir por 20 anos – concedida ao escravo Paulino Crioulo.',101);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (374,4,'B','permite verificar que a revogação de liberdade por ingratidão era uma possibilidade legal, amparada pelo Título 63 do Livro IV das Ordenações Filipinas.',101);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (375,5,'C','apresenta a carta de alforria como um instrumento utilizado pelo senhor para garantir a o trabalho e fidelidade do escravo ao longo de muitos anos.',101);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (376,0,'D','demonstra como a possibilidade da revogação da liberdade tornava a alforria pouco desejada pelos escravos.',101);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (377,0,'A','a autora discorda das interpretações históricas clássicas que definem a Guerra dos Emboabas como uma revolta nativista, afirmando que não havia no século XVIII um sentimento de nação brasileira.',102);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (378,5,'B','segundo a interpretação do IHGB, nas disputas que envolveram paulistas e emboabas, germinava o sentimento nacionalista, sendo possível, portanto, compor uma correspondência histórica entre esse episódio e os movimentos de independência no século seguinte.',102);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (379,4,'C','os emboabas, assim denominados de forma pejorativa pelos bandeirantes paulistas, eram um grupo heterogêneo de portugueses e brasileiros de diversas regiões, como a Bahia.',102);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (380,1,'D','o debate proposto pela autora busca pensar o episódio dessa guerra a partir de diferentes características a ele atribuídas.',102);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (381,1,'A','o documento demonstra um profundo desejo por reformas políticas e sociais, de modo a alinhar o país à tendência republicana existente na América.',103);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (382,5,'B','a América a que o Manifesto Republicano faz referência era composta por repúblicas consolidadas e outras em processo de formação.',103);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (383,0,'C','por meio do Manifesto Republicano de 1870, os autores buscavam reformar o Império por vias pacíficas e diplomáticas.',103);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (384,4,'D','o Manifesto Republicano de 1870 foi escrito no único país naquele momento, nas Américas, a possuir sistema monárquico.',103);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (385,1,'A','a organização dos guerreiros revoltosos foi inspirada na lenda de Carlos Magno e seus Doze Pares de França.',104);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (386,0,'B','teve caráter religioso e definiu-se pelo fanatismo dos camponeses expulsos das terras onde trabalhavam.',104);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (387,5,'C','a guerra resultou dos limites impostos aos mandonismos locais, em conseqüência do envolvimento dos “coronéis” nas questões dos limites das terras; os sertanejos passaram a perceber de maneira mais clara a violência a que estavam submetidos.',104);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (388,4,'D','a questão da terra revertida com a instalação da estrada de ferro aparece como causa secundária que levou a desestabilizações nas vidas dos sertanejos, ao desequilíbrio de relações políticas locais e familiares e, por fim, a um conflito sangrento.',104);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (389,5,'A','o homem branco está ligado à idéia de civilização e o índio associado à natureza.',105);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (390,4,'B','o engenheiro posiciona-se de modo confortável, enquanto o índio parece deslocado dentro de seu próprio ambiente.',105);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (391,1,'C','a abertura de caminhos de ferro proporcionou o contato com nativos.',105);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (392,0,'D','a chegada da estrada de ferro colocou homem branco e índio em situação de igualdade.',105);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (393,0,'A','tratava-se de um jornal de propaganda política da monarquia dos Bragança.',106);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (394,5,'B','tratava-se de mais um ato considerado civilizatório no interior da política de metropolização da cidade do Rio de Janeiro levada a cabo pelo governo do Príncipe Regente D. João.',106);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (395,1,'C','era importante receber notícias da guerra que transcorria em solo europeu e desencadeara a transplantação da corte.',106);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (396,4,'D','apesar de serem voltadas para uma camada letrada da corte e de outras partes do Brasil, as notícias eram lidas em voz alta em botequins, armazéns e praças, difundindo-se entre as camadas populares.',106);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (397,4,'A','a questão da terra ganhou outra dimensão no Brasil a partir daquela data, uma vez que o State definiu a transferência do seu domínio ao particular, porém foram gerados muitos papéis falsos quanto à posse da terra.',107);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (398,5,'B','a legislação da terra foi articulada pela elite do café, pois com ela foi incentivada a vinda de mão de obra estrangeira para substituição do trabalho escravo.',107);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (399,0,'C','a Lei de Terras de 1850 solucionou a questão agrária no Brasil, ao facilitar o acesso à posse de terras pelo trabalho.',107);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (400,1,'D','até aquela data, a questão da terra ainda não tinha uma legislação específica no Brasil e seu domínio era garantido pelo direito de sesmaria.',107);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (401,1,'A','a mensagem presidencial faz referencia à vinda de astrônomos europeus à cidade de Sobral, no Ceará, indicando as medidas tomadas para a recepção e deslocamento desses cientistas.',108);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (402,4,'B','o Ministério das Relações Exteriores e da Agricultura, Industria e Commercio lidou com a visita dos cientistas, já que o Brasil não possuía universidades ou um Ministério de Ciência e Tecnologia.',108);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (403,0,'C','naquele momento, a cidade de Sobral era a única a possuir um observatório astronômico no Brasil.',108);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (404,5,'D','Sobral era um local privilegiado para observar o eclipse total do sol e dessa forma comprovar a teoria da relatividade geral de Albert Einstein.',108);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (405,1,'A','as imagens vinculam o trabalho doméstico e a utilização de eletrodomésticos à figura feminina.',109);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (406,5,'B','a propaganda vincula-se ao aumento do consumo de bens industrializados pelas classes médias no Brasil.',109);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (407,4,'C','a propaganda propõe que a condição para uma vida familiar feliz estava condicionada ao consumo e à utilização de aparelhos elétricos para tornar o trabalho doméstico mais prático e eficiente.',109);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (408,0,'D','a propaganda mostra que os eletrodomésticos davam autonomia para que a mulher se realizasse profissionalmente.',109);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (409,5,'A','a versão nacional de Lili Marlene adapta a letra da canção ao contexto brasileiro, trazendo referências aos locais de treinamento e de combate dos pracinhas e fazendo menção a influências culturais estrangeiras e aos valores da luta contra a opressão.',110);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (410,4,'B','a música faz referência ao símbolo e grito de guerra do Primeiro Grupo de Aviação de Caça da Força Aérea Brasileira; “Senta a Pua!”.',110);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (411,1,'C','a versão brasileira e a canção original falam sobre o amor entre um soldado e sua amada, mas na versão nacional o soldado alemão é tratado como inimigo.',110);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (412,0,'D','a parte final da versão brasileira de Lili Marlene, que se refere a “louros da vitória” e “escrever uma página da História”, sustenta-se no fato de que as tropas brasileiras não tiveram baixas durante a Segunda Guerra.',110);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (413,4,'A','o historiador procurou dar um tom romanceado ao momento da escrita da Carta, de forma a atrair e cativar seu público leitor.',111);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (414,1,'B','ao destacar a importância de Caminha e da Carta do Descobrimento, ele destacava a importância da descoberta que havia feito, do documento mais antigo relativo à existência do Brasil.',111);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (415,0,'C','Varnhagen não escreveu como um verdadeiro historiador do século XIX, pois estava romanceando e imaginando acontecimentos que não teria como conhecer de fato.',111);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (416,5,'D','os acontecimentos da noite em que a carta foi escrita, assim narrados, são verossímeis.',111);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (417,1,'A','a visão do governo norte-americano em relação à ditadura militar brasileira (1964-1985) alterou-se a partir da pressão de ativistas, exilados e grupos da sociedade civil.',112);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (418,4,'B','o apoio dos EUA ao golpe de 1964 insere-se na lógica da Guerra Fria e do anticomunismo presentes entre norte-americanos e militares brasileiros.',112);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (419,5,'C','a troca de informações entre grupos da sociedade civil no Brasil e dos EUA burlava o controle da censura e contribuía para o questionamento do apoio dado pelo governo americano aos militares no Brasil.',112);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (420,0,'D','a prática da tortura no Brasil só foi observada como um fenômeno repulsivo após a descoberta de ações semelhantes durante a Guerra do Vietnã.',112);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (421,1,'A','as ações dos ativistas que denunciavam a tortura no Brasil contribuíram para que se popularizasse nos EUA a noção de direitos humanos.',113);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (422,4,'B','as legislações que proibiam ajuda financeira dos EUA a países que desrespeitassem os direitos humanos eram uma forma de pressionar o governo brasileiro e o empresariado, dadas as intensas relações econômicas entre os dois países.',113);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (423,5,'C','desde a doutrina Monroe (1823), a América Latina é para os Estados Unidos uma região de interferência política. Exemplos recentes, além do caso brasileiro, foi o apoio aos regimes militares no Chile, Argentina e Uruguai.',113);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (424,0,'D','os EUA foram os maiores responsáveis tanto pela criação quanto pelo fim da ditadura no Brasil.',113);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (425,1,'A','devido à noção da época sobre a indignidade do trabalho, o jesuíta propõe “paciência” aos escravos como forma de iludi-los e, assim, condicioná-los à realização das tarefas nas lavouras.',114);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (426,4,'B','Vieira utiliza-se de passagens bíblicas da vida de Cristo para confortar os negros sobre sua condição de escravos.',114);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (427,5,'C','a partir da lógica social, política e econômica de seu período, Vieira proporciona aos negros um sentimento de pertencimento ao mundo colonial na medida em que os define como mártires dessa sociedade brasileira.',114);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (428,0,'D','ao evocar os episódios bíblicos da Paixão de Cristo e compará-los à situação do negro no Brasil, Vieira legitima o sistema escravocrata vigente na colônia.',114);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (429,5,'A','a perspectiva histórica de Schwartz rompe com a dualidade de vítimas e opressores para um estudo da sociedade da grande lavoura, frisando a complexidade existente na relação entre eles.',115);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (430,1,'B','a história colonial brasileira está fortemente relacionada a um discurso produzido pelos latifundiários, sendo eles tanto os fornecedores de documentos para esse recontar histórico como o seu personagem central.',115);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (431,4,'C','pensar a escravidão como parte de “uma estrutura mais abrangente de relações sociais e econômicas” é uma forma de não correr o risco de privilegiar mais uma vez, agora na figura do escravo, um único caminho para a análise da sociedade colonial.',115);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (432,0,'D','o historiador indica que o tipo de documento utilizado determina a interpretação possível sobre o passado.',115);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (433,4,'A','ex-voto constitui uma forma de “agradecimento” por uma graça alcançada.',116);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (434,1,'B','as imagens retratam dois acidentes com desfecho não trágico, um relativo à queda de cavalo de D. Pedro I e outro sobre o afogamento de um escravo.',116);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (435,5,'C','as imagens dos ex-votos narram um contato direto e particular entre o fiel e seu santo intercessor.',116);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (436,0,'D','os ex-votos desde o século XVIII dizem respeito à uma prática das camadas sociais menos favorecidas.',116);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (437,1,'A','os habitantes dos povoados, livres ou escravizados, distribuíam-se de forma esparsa pelo território.',117);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (438,5,'B','a descrição da técnica construtiva e dos modos de morar na colônia tem por referência a forma de construir e morar na Europa.',117);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (439,0,'C','a descrição confirma que no Brasil colonial inexistiam técnicas construtivas.',117);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (440,4,'D','o texto associa a beleza dos edifícios ao uso de técnicas e materiais modernos.',117);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (441,0,'A','as representações européias como as Narrenschiff, trionfi e Charriots foram transpostas para o Brasil colonial.',118);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (442,4,'B','carros alegóricos foram introduzidos nas festividades coloniais com o objetivo de exibir o poder religioso ou real à população.',118);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (443,1,'C','os eventos públicos na colônia não se limitavam às festividades de caráter religioso.',118);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (444,5,'D','as representações barrocas da colônia brasileira transformaram as práticas festivas portuguesas, fundindo encenações religiosas e teatrais.',118);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (445,0,'A','a indenização mencionada no texto procurava compensar os escravos por seus anos de cativeiro.',119);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (446,4,'B','o texto expressa a opinião de grupos monarquistas absolutistas.',119);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (447,1,'C','o autor da carta compara a abolição no Brasil a outros movimentos no mundo.',119);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (448,5,'D','o movimento abolicionista teve participação de ativistas de differentes setores sociais organizados em associações antiescravistas e contou com intercâmbio de idéias e ações internacionais.',119);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (449,1,'A','Não são apenas as experiências de rotina dentro das fábricas ou acontecimentos como as greves que permitem compreender a realidade dos trabalhadores.',121);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (450,0,'B','No mundo do trabalho a presença das mulheres é menor e incidental.',121);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (451,5,'C','Os trabalhadores compartilham experiências e valores que implicam a criação de identidades de classe.',121);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (452,4,'D','Os mundos do trabalho estão também nas práticas cotidianas, que incluem o lazer e outras formas de sociabilidade.',121);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (453,5,'A','A prática de voto descrita como “cabresto” estava na base da política dos governadores posta em prática pelos grupos oligárquicos na chamada República Velha, com o objetivo de manterem-se no poder.',122);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (454,1,'B','A charge mostra o eleitor na forma de um burro sendo levado até as urnas pelo político e recebido por uma mulher representando a “soberania”.',122);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (455,4,'C','A charge representa uma das fraudes eleitorais da Primeira República, quando o eleitor recebia e depositava na urna um papel com o nome do candidato do coronel da região, sem fazer sua própria escolha.',122);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (456,0,'D','A charge mostra o papel da mulher como eleitora na década de 1920, representada no documento pela soberania.',122);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (457,1,'A','Assim como o cortiço é descrito como se fosse um organismo vivo, as personagens são descritas confundindo-se com os próprios animais que lá viviam.',123);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (458,4,'B','O autor trata a questão dos cortiços como uma representação coletiva que trazia incômodo a outros grupos sociais.',123);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (459,0,'C','Os cortiços foram os maiores culpados pelo crescimento desordenado da cidade do Rio de Janeiro e pela proliferação de doenças.',123);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (460,5,'D','O cortiço é um reflexo de um planejamento urbano que não contemplava todas as classes sociais.',123);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (461,4,'A','As populações pré-históricas organizadas adaptam-se de diferentes maneiras ao meio em que vivem.',124);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (462,5,'B','A imagem estereotipada do homem pré-histórico criada no século XIX ainda é difundida pelos meios de comunicação como cinema e televisão.',124);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (463,1,'C','O estereótipo europeu do homem pré-histórico não é aplicável aos primeiros habitantes do território hoje chamado de Brasil.',124);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (464,0,'D','O homem pré-histórico de regiões tropicais vivia em um clima ameno, sem inimigos naturais e com muitos materiais a sua disposição.',124);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (465,0,'A','Os portugueses ignoravam as minas encontradas uma vez que os metais e pedras preciosas não eram, naquele momento, importantes para a economia europeia.',125);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (466,4,'B','A comparação entre portugueses e caranguejos se explica pela ocupação exclusivamente litorânea do território.',125);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (467,5,'C','Os portugueses são retratados como os que souberam conquistar, mas não souberam explorar de forma satisfatória, as terras conquistadas.',125);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (468,1,'D','A linha imaginária indivisível a que se refere o texto é a estabelecida pelo Tratado de Tordesilhas em 1494.',125);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (469,5,'A','A propaganda afirma que o papel social da mulher e a qualidade do café permaneceram inalterados ao longo do tempo.',126);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (470,1,'B','Na propaganda, a passagem do tempo é demonstrada pelas vestimentas da figura feminina e dos edifícios ao fundo.',126);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (471,0,'C','O consumo de café se popularizou no Brasil a partir de 1902, como demonstra a propaganda.',126);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (472,4,'D','A propaganda reflete o processo de industrialização pelo qual o Brasil passava, atingindo o beneficiamento de alimentos, como o café.',126);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (473,1,'A','Trata-se das memórias de um migrante nortista que veio em busca de uma vida melhor para uma grande cidade emergente e trabalhou na construção civil de obras importantes.',127);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (474,0,'B','As populações migrantes do Norte e do Nordeste não têm acesso a moradia e escola no Sul e Sudeste.',127);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (475,4,'C','Lúcio Barbosa trabalha com a ideia metafórica, e ao mesmo tempo real, de que as metrópoles brasileiras do Sul e Sudeste foram construídas pelos migrantes do Norte e Nordeste do Brasil.',127);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (476,5,'D','O autor explora a questão da venda de mão de obra produtiva, dentro de um ciclo de exploração no qual quem produz não tem acesso ao consumo do produto acabado.',127);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (477,4,'A','É possível concluir que o plano de integração nacional se baseou na ampliação da malha rodoviária, como a rodovia Acre-Brasília sugere.',128);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (478,5,'B','Interiorização, rodovia e progresso eram idéias afins que acabavam por se chocar com outras realidades existentes no interior do Brasil.',128);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (479,0,'C','O plano de integração nacional possibilitou que o município de Rio Branco, no Estado do Acre, até então completamente isolado, se conectasse ao restante do país.',128);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (480,1,'D','A fotografia retrata o contexto das ações político-econômicas que visavam à integração nacional ao longo das décadas de 1950 a 1970.',128);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (481,0,'A','Cada geração de historiadores renega os estudos anteriores, fragmentando o conhecimento em história do Brasil.',129);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (482,1,'B','A autora descreve como a produção recente sobre a história do Brasil foi se renovando e propondo novas abordagens a temas de estudo já conhecidos.',129);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (483,5,'C','Abandonar a dualidade Brasil-Portugal e entender o Brasil como parte do Império Português amplia a compreensão dos processos de colonização, domínio e escravidão.',129);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (484,4,'D','A história da escravidão que considera as experiências dos escravos para além da submissão ou da revolta implica considerá-los como sujeitos de sua própria história.',129);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (485,1,'A','A imagem faz referência direta à crise política nos últimos meses do Império.',131);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (486,5,'B','Ao colocar a imagem da “Republica” acima e afastando-se dos símbolos do Império aponta-se para a superação de um sistema de governo ultrapassado para o país.',131);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (487,0,'C','Trata-se de uma crítica ao movimento republicano que ao crescer traz destruição à ordem vigente.',131);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (488,4,'D','A imagem nos permite estabelecer “O Mequetrefe” como um jornal marcado pela defesa da república e contra o State Monárquico.',131);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (489,0,'A','Por conter informações científicas revolucionárias, o documento foi ocultado até meados do século XIX.',132);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (490,4,'B','A biografia de Mestre João demonstra as ricas experiências dos homens que se lançavam aos mares no século XV, os quais puderam conhecer as mais diversas culturas e valer-se do novo conhecimento adquirido em seus empreendimentos náuticos.',132);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (491,1,'C','A relação com a cultura árabe foi fundamental para que os portugueses e espanhóis pudessem alcançar novos territórios.',132);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (492,5,'D','O histórico de perseguições religiosas vividas pelo Mestre João sugere que a história das navegações seja considerada para além dos interesses comerciais do período.',132);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (493,4,'A','A descoberta em 1843 da carta escrita por Mestre João em 1500 é importante porque ajuda a entender, através dos registros da história náutica, a cultura dos homens que se aventuraram pelos mares em busca de novas terras.',133);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (494,0,'B','Conhecer o céu brasileiro era fundamental para a realização de navegações vindouras, embora não contribuísse para a ocupação e dominação dos novos territórios.',133);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (495,5,'C','A comparação realizada pelo historiador entre o mapa das estrelas no início das navegações e o uso atual do GPS é um esforço de aproximar diferentes experiências históricas e de refletir sobre as diversas técnicas desenvolvidas pelo homem ao longo do tempo.',133);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (496,1,'D','A importância do Cruzeiro do Sul foi apropriada como um símbolo de patriotismo pelo discurso republicano no final do século XIX.',133);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (497,5,'A','Possui traços de xenofobia, marcando os estrangeiros como preferidos pela doença.',134);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (498,1,'B','Trata-se de um comunicado da comissão médica para evitar, entre a população, o pânico causado pela possibilidade de uma epidemia de febre amarela.',134);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (499,4,'C','Revela o pouco conhecimento sobre a doença e sua forma propagação.',134);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (500,0,'D','Descreve a febre amarela como uma doença causada pelo clima tropical e que acomete os mais pobres.',134);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (501,4,'A','A construção de uma fortaleza e a fundação de uma povoação na Baía de Todos os Santos era uma forma de assegurar a presença administrativa da Coroa portuguesa.',135);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (502,5,'B','O documento revela uma estrutura de poder baseada em confiança e fidelidade na relação entre o Rei e o Governador Geral, que atuaria como representante do poder real em terras coloniais.',135);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (503,0,'C','O sucesso encontrado por Tomé de Souza na execução do Regimento imposto pelo rei D. João III na região da Bahia fez com que ele ficasse no Nordeste e não estendesse seus compromissos para as demais capitanias.',135);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (504,1,'D','O rei D. João III discorre sobre sua expectativa em relação à atuação de Tomé de Souza em terras brasileiras, indicando seus compromissos em conservar, fortalecer e povoar as capitanias hereditárias.',135);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (505,0,'A','Segundo o texto, turismo e história compartilham de funções semelhantes: enquanto o turismo nos diverte ao nos levar a visitar outros lugares, a história nos diverte ao nos levar a visitar outras épocas.',136);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (506,4,'B','A história oral pode transformar os conteúdos tradicionais e a compreensão deles, ao devolver às pessoas comuns a importância que possuem dentro de processos que elas próprias vivenciaram.',136);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (507,1,'C','O autor identifica que, quando a finalidade social da história mostra-se obscura, ela pode ser feita de forma manipuladora ou desinteressada.',136);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (508,5,'D','A história oral é um método de recolher relatos e testemunhos sobre eventos do passado, mesmo que seus resultados, assim como os gerados por outros métodos de pesquisa, não sejam necessariamente os mais completos ou verdadeiros.',136);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (509,1,'A','Em finais do século XIX e início do século XX o matrimônio para a mulher tem conotação de alicerce e estabilidade de vida.',137);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (510,0,'B','A rebeldia da mulher e a formação do operariado feminino descritos no texto II é consequência direta da domesticação da mulher descrita no texto I.',137);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (511,5,'C','O texto I reafirma que o papel da mulher limita-se ao ambiente doméstico e reproduz uma ideologia conservadora veiculada em um jornal caracteristicamente operário.',137);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (512,4,'D','A ideia de uma cultura feminina universal que aparece no texto I repete-se de forma coerente referindo-se ao operariado feminino descrito no texto II.',137);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (513,5,'A','A pobreza é representada na obra através de personagens “de segunda classe” que chegam em trens buscando melhores oportunidades de trabalho nos centros urbanos.',138);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (514,1,'B','As cores utilizadas e a expressão dos personagens na obra sugerem um clima sombrio; seus pés descalços e roupas simples denunciam sua origem humilde.',138);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (515,4,'C','Trata-se de uma obra que, ao retratar um grupo familiar desembarcando numa estação de trem, esboça uma preocupação com a situação social resultante do processo de industrialização no Brasil.',138);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (516,0,'D','Tarsila do Amaral era uma exceção dentro do movimento modernista brasileiro por retratar a temática social em sua obra.',138);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (517,4,'A','Em Morte e Vida Severina, João Cabral de Melo Neto critica o latifúndio e o coronelismo ainda presentes no Brasil do século XX.',139);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (518,0,'B','Nos versos “é a parte que te cabe neste latifúndio/ não é cova grande é cova medida/ é a terra que querias ver dividida”, o trabalhador rural sabe o que lhe pertence e assim se contenta.',139);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (519,1,'C','O autor descreve no poema as tensões do campo por meio de jogos de palavras que alternam os ciclos de morte e vida.',139);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (520,5,'D','No Auto, a parte de terra que coube ao sertanejo é uma ironia que trabalha com a realidade das forças desproporcionais em disputa em um Brasil latifundiário.',139);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (521,4,'A','O antigo convento de São José é símbolo das remanescentes missões religiosas nas terras amazônicas...',141);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (522,1,'B','O documento evidencia os processos de ocupação das terras interioranas do Brasil no século XVIII...',141);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (523,0,'C','O listagem apresentada no documento descreve o esforço de Francisco de Souza Coutinho...',141);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (524,5,'D','A nomeação do agrônomo francês Michel Grenoullier, emigrado de Caiena, como primeiro diretor do Jardim Botânico aponta para as rivalidades territoriais entre França e Brasil...',141);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (525,1,'A','A identificação da figura de José Bonifácio como “Patriarca da Independência” ocorreu no próprio desenrolar das primeiras décadas do império...',142);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (526,0,'B','A perpetuação de José Bonifácio como “Patriarca da Independência” decorre de sua destreza em lidar com os interesses antagônicos na política imperial.',142);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (527,5,'C','A construção da figura mítica dos pais fundadores de uma nação está na base dos debates sobre Independência e Nacionalismo.',142);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (528,4,'D','Há uma ambiguidade na figura e nas ações de José Bonifácio que permitiu que ele fosse aceito e rejeitado...',142);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (529,5,'A','Intelectuais republicanos apresentaram inúmeros projetos de estandartes brasileiros...',143);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (530,4,'B','Esta bandeira do Brasil é análoga à dos Estados Unidos, o que mostra que foi inspirada nos ideais de liberdade...',143);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (531,1,'C','Trata-se da primeira bandeira do Brasil republicano, criada em 1889, sendo, contudo, um estandarte provisório.',143);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (532,0,'D','A analogia com a bandeira dos Estados Unidos é um anacronismo, pois os ideais de liberdade estadunidenses provêm do século XVIII...',143);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (533,0,'A','Apesar de os comerciantes franceses serem numericamente superiores, sua influência foi parca no comércio urbano...',144);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (534,5,'B','As mercadorias e os hábitos franceses foram absorvidos e caracterizaram determinados espaços urbanos no Rio de Janeiro. Por outro lado, o Império comercial britânico teve escala territorial e demandou espaços de escoamento estratégicos na cidade.',144);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (535,4,'C','O autor, ao estudar os anúncios de jornais e as crônicas de estrangeiros... caracteriza cada nacionalidade pelo tipo de comércio que realiza.',144);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (536,1,'D','Os espaços ocupados pelos comerciantes no Rio de Janeiro foram orientados pelos diferentes tipos de mercadorias...',144);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (537,4,'A','O protesto dos estudantes contra o governo militar representado na figura do Presidente da República se inscrevia numa série de movimentos contestatórios...',145);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (538,0,'B','Embora contasse com cerca de 5 mil manifestantes, a Novembrada foi um movimento que acabou sem enfrentamento com a polícia local...',145);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (539,1,'C','A imagem mostra um grupo de manifestantes segurando uma placa de bronze doada pelo presidente João Batista Figueiredo...',145);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (540,5,'D','A Novembrada ao mesmo tempo critica a homenagem prestada ao “marechal de ferro” e o governo militar a ela contemporâneo, inscrevendo-se como um movimento contestatório no contexto do fim da ditadura militar.',145);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (541,5,'A','O fato de os manifestantes arrancarem a placa da Praça XV de novembro significa a rejeição da memória invocada pela placa.',146);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (542,1,'B','Pode-se inferir que o monumento a Floriano Peixoto – placa de bronze – é um documento histórico.',146);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (543,0,'C','O ato perde o significado por se tratar de depredação do patrimônio público.',146);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (544,4,'D','Pode-se dizer que a placa materializa a imposição de uma memória oficial que ressalta de forma positiva a imagem de Floriano Peixoto.',146);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (545,1,'A','Propõem a limitação dos poderes dos feitores de acordo com a sua posição...',147);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (546,4,'B','Apontam para a existência de differentes graus de importância entre os indivíduos no interior dos engenhos...',147);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (547,5,'C','Apresentam o castigo aos cativos como algo necessário para a manutenção da ordem, desde que dentro de limites tidos como aceitáveis por senhores e escravos.',147);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (548,0,'D','Demonstram que aos escravos não era dada a possibilidade de acusar um feitor que lhes maltratassem.',147);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (549,0,'A','Os termos e a linguagem empregados na revista para descrever os novos e diferentes eventos esportivos demonstram o caráter popular do periódico do início do século XX.',148);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (550,5,'B','A seção da revista \"A Vida Moderna\" evidencia novos e diferentes espaços de sociabilidade que começavam a se formar na cidade em torno do esporte, o que sugeria certo caráter cosmopolita.',148);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (551,4,'C','Apesar de o futebol passar por um momento de popularização do esporte, ele ainda estava muito ligado à sua origem inglesa, tal como a linguagem e os termos atestam.',148);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (552,1,'D','A seção da revista apresenta variados eventos sociais e esportivos que começavam a se popularizar na cidade de São Paulo da década de 1910...',148);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (553,5,'A','A empresa ambicionava adaptar o trabalhador aos ritmos da sua produção, por meio da disciplina e do controle dos espaços.',149);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (554,0,'B','Essa empreitada fordista fracassou, pois o Brasil ainda não estava preparado para o modo de produção capitalista.',149);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (555,1,'C','Nos relatos, os antigos trabalhadores lamentam o estado de abandono em que a sua cidade se encontrava na década de 1990.',149);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (556,4,'D','O controle da empresa estendia-se além do ambiente de trabalho e adentrava a vida privada dos trabalhadores.',149);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (557,1,'A','Uma das crenças daquele período era que os vapores (miasmas) emitidos pelos mortos transmitiam doenças aos vivos.',150);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (558,4,'B','A rejeição ao cemitério na Bahia naquele momento culminou em uma revolta popular que ficou conhecida como Cemiterada.',150);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (559,0,'C','As duas petições se contrapõem à inauguração do cemitério por considerá-lo um foco de doenças.',150);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (560,5,'D','A mudança dos enterros das igrejas para os cemitérios implicou na secularização dos procedimentos fúnebres.',150);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (561,5,'A','O ato de chorar na cultura dos indígenas da região da Bahia possui uma multiplicidade de significados, captado pelo cronista sob um certo olhar de estranhamento e incompreensão.',151);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (562,1,'B','A crônica do padre Fernão Cardim descreve algumas práticas culturais dos indígenas da região da Bahia do séc. XVI...',151);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (563,4,'C','O autor utiliza-se de conceitos próprios de sua cultura ao tentar \"traduzir\" os fenômenos culturais dos indígenas americanos...',151);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (564,0,'D','Apesar de serem diferentes os costumes de recepcionar os \"estrangeiros\" em comparação com os da cultura ocidental...',151);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (565,0,'A','O apelo por “direitos coletivos” revela a falta de conhecimento por parte dos indígenas...',152);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (566,5,'B','O documento revela o interesse dos povos indígenas em defender seu papel de atores políticos, além de reivindicaram a segurança das suas culturas, que tem a natureza como fundamento da sua economia e garante a manutenção da vida.',152);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (567,1,'C','Os povos indígenas almejam incluir seus interesses coletivos nas necessidades apresentadas pela comissão da ONU...',152);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (568,4,'D','A sugestão de enfatizar o termo “genocídio dos povos indígenas” na Carta da Terra revela uma tensão vivida por esses povos...',152);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (569,4,'A','O restauro e as conseqüentes descobertas são meios de reconhecermos uma narrativa histórica que, nesse caso de Congonhas, conta o processo de construção e interpretação do Santuário...',153);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (570,0,'B','O esquecimento da obra ímpar de Mestre Ataíde durante um longo período de tempo deve-se ao desconhecimento das técnicas de restauro...',153);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (571,5,'C','O conjunto de obras que configura o Santuário de Matosinhos e que inclui pintura, escultura e arquitetura, representa uma cultura artística barroca do período colonial; mas à finalização desse complexo ocorreram interferências que por muito tempo deram destaque apenas às esculturas.',153);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (572,1,'D','O trabalho de restauração do Santuário de Bom Jesus de Matosinhos em 2009 revelou a existência de cenários pintados por Mestre Ataíde em algumas das capelas...',153);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (573,1,'A','A charge brinca com a abreviação do Ato Institucional no 5 veiculando o protesto e mobilização ao pedir pela anistia de presos e exilados políticos.',154);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (574,5,'B','Na charge, há uma estreita relação de causa e conseqüência entre o Ato Institucional no 5 e a campanha de Anistia do crimes políticos.',154);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (575,4,'C','O contexto de organização da campanha pela anistia demonstra uma primeira grande organização da sociedade civil em torno dos direitos políticos e civis cassados...',154);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (576,0,'D','A veiculação desse tipo de charge em jornais como \"O Pasquim\" demonstrava a franca abertura do governo em negociar o perdão aos crimes políticos...',154);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (577,1,'A','É um relatório em forma de carta, datilografado e contendo erros de ortografia.',156);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (578,5,'B','Está armazenado em arquivo na condição de documento histórico, embora se refira a um evento hipotético.',156);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (579,0,'C','Dada a gravidade da denúncia e para proteger-se, o autor da missiva evitou registrar seu nome de forma legível.',156);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (580,4,'D','O relator fornece informações que ouviu de outra pessoa, que considera confiável.',156);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (581,5,'A','O conteúdo da carta mostra a ação do movimento Integralista que ora pende para a legalidade ora volta-se para a realização de um golpe para alcançar o poder.',157);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (582,1,'B','O documento relata as possíveis ações que os membros do movimento Integralista poderiam tomar entre os dias 4 e 13 de novembro de 1937.',157);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (583,4,'C','O contexto de produção do documento era caracterizado pelo acirramento político entre os movimentos de extrema esquerda, como a Aliança Libertadora Nacional (ANL) e de extrema direita, como a Ação Integralista Brasileira (AIB).',157);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (584,0,'D','O movimento Integralista era bem aceito pelo governo Vargas, de modo que ganhou apoio dos principais escalões do governo ao longo da década de 1930.',157);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (585,0,'A','O terrível massacre no porão do brigue, sobre o qual as autoridades não se responsabilizaram, forçou a imediata adesão do Pará à Independência do Brasil.',158);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (586,4,'B','O Grão-Pará, que na época incluía o Amazonas, foi o último estado a aderir ao Império e em 1823 representava um dos últimos redutos portugueses em terras brasileiras.',158);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (587,5,'C','A referência às Guerras Púnicas mostra que os estudiosos lançaram mão de eventos de outras épocas e lugares para construir uma explicação histórica sobre o massacre.',158);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (588,1,'D','Os acontecimentos, aos serem relembrados 100 anos após ocorrerem, trouxeram à tona interpretações sobre os vencedores e os perdedores no evento.',158);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (589,4,'A','O homem citado na Sinfonia é uma representação dos milhares de trabalhadores que migraram para a região a fim de trabalhar principalmente na atividade da construção civil, chamados de candangos.',159);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (590,0,'B','A Sinfonia é uma crítica à destruição do ambiente natural a partir da construção da nova capital do país.',159);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (591,1,'C','O texto descreve o aspecto selvagem e a solidão agreste da região do cerrado, a chegada do homem com fins exploratórios e a engenharia e o trabalho humano necessários para a construção de uma cidade.',159);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (592,5,'D','A composição retrata o desafio de transladar a capital do Brasil para o interior do território chamando a atenção para a atuação do homem que domina e transforma a natureza.',159);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (593,0,'A','A opulência impressa nos ornamentos das igrejas barrocas revelam a contradição do discurso católico do século XVII...',160);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (594,5,'B','O estilo barroco, introduzido no Brasil pelos jesuítas, era caracterizado pela profusão de formas e ornamentos exuberantes...',160);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (595,4,'C','O fato de a igreja mais ricamente ornamentada estar na Bahia, sendo que as principais fontes de extração de ouro estivam nas Minas Gerais, revela o poder administrativo da então capital colonial.',160);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (596,1,'D','A construção da Igreja está relacionada ao período de descobertas das jazidas de ouro no interior do Brasil.',160);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (597,5,'A','A junção entre a prática médica de identificar a loucura e a ação do Estado de criminalizá-la e puni-la, instituindo-a como um problema social.',161);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (598,0,'B','O quanto o espaço urbano naquela época era perigoso e degradado.',161);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (599,1,'C','Como certos grupos que ocupavam o espaço público eram vistos como incômodos a serem retirados do convívio social.',161);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (600,4,'D','A normatização da doença mental no Brasil do século XIX se confunde com a mentalidade da higiene urbana e social e com a marginalização de quem diverge dos padrões vigentes.',161);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (601,0,'A','Apesar de sua argumentação, a imagem de Getúlio Vargas ficou irremediavelmente maculada aos olhos do povo por seu ato de suicídio.',162);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (602,4,'B','Quando diz “(...) Escolho este meio de estar sempre convosco...\" remete sua morte à ascensão do próprio Cristo a Deus Pai.',162);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (603,5,'C','Há uma argumentação eficiente para a perpetuação de uma imagem de si mesmo passível de idolatria, que o potencializa como herói que deu a vida pelo seu povo.',162);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (604,1,'D','Getúlio exalta seu nacionalismo e reforça a imagem do governante que mais lutou para o bem do trabalhador brasileiro, opondo-se aos interesses estrangeiros.',162);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (605,4,'A','O lugar que o mural ocupa tem o objetivo de estabelecer um marco de exposição pública em um espaço estratégico, reforçando a importância da arte e do tema que ela representa.',163);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (606,1,'B','Os temas centrais da pintura são representados ao fundo pela figuras dos portugueses, dos bandeirantes e dos índios. À frente, vê-se a imagem estereotipada do gaúcho, um núcleo familiar e o trabalho na agricultura.',163);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (607,5,'C','A narrativa da obra é construída e organizada numa perspectiva harmoniosa cuja representação evidencia o convívio consensual entre os diferentes grupos que fizeram parte do processo de formação do Rio Grande do Sul.',163);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (608,0,'D','Embora verossímil, a arte mural em espaços públicos é destituída de conotações políticas...',163);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (609,1,'A','Em seu pedido o professor aludiu à convivência conflituosa entre brancos e negros para assim conseguir a dispensa do exame para professores.',164);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (610,0,'B','A supressão dos termos “cor preta” e “pardos” no parecer do Conselho Diretor e a utilização da expressão “de cor” denotam o mascaramento de ideais racistas baseados no darwinismo social.',164);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (611,4,'C','Um dos argumentos do suplicante é o de que “por este ser também preto” aquelas crianças estariam mais bem acolhidas em sua escola.',164);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (612,5,'D','A existência de um exame que habilitava o professor e garantia o funcionamento da escola, indica que em meados do século XIX a educação passava a ser regulada pelo Estado.',164);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (613,4,'A','O quilombo do Quariterê, assim como muitos outros, era organizado a partir de formas de governo tradicionais na África...',165);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (614,5,'B','A existência de punições violentas contra os quilombolas que ameaçavam a segurança e o sigilo sobre a localização dos quilombos contesta a interpretação de que esses locais eram comunidades idílicas.',165);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (615,1,'C','Por meio de relatos e memórias de indivíduos que exerciam cargos administrativos e militares e que perseguiam os quilombos é possível conhecer as formas de organização quilombolas.',165);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (616,0,'D','A ausência de complexidade social na organização interna dos quilombos os tornavam experiências efêmeras e de curta duração.',165);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (617,4,'A','O fato de “não existir”, segundo a depoente, revela a condição de esquecimento da trajetória das mulheres na condição de exiladas, já que a maioria dos relatos de que se dispõe diz respeito aos homens.',166);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (618,1,'B','O trecho da entrevista se refere ao depoimento de uma mulher que relata a condição de exilada decorrente da perseguição às pessoas envolvidas com temas contrários ao regime militar.',166);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (619,0,'C','A fala revela que a condição de exílio impedia a configuração de um núcleo familiar estável.',166);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (620,5,'D','O fato de serem exilados não apenas os perseguidos politicamente, mas também suas esposas... possibilita pensar na existência não de um exílio, mas de vários exílios.',166);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (621,1,'A','A cena central do operário morto - provavelmente em uma queda - é vista do alto, como se o espectador do quadro também fosse um operário no alto de um andaime.',167);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (622,0,'B','O pintor denuncia a indiferença dos operários, que parecem não se importar com o destino trágico de seu colega.',167);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (623,5,'C','O pintor também retrata um momento de dinamismo da construção civil brasileira iniciada na década de 1940 e caracterizada por grandes obras públicas em concreto armado.',167);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (624,4,'D','As condições precárias de trabalho são enfatizadas pelas cordas frágeis, grandes alturas e ausência de equipamentos de segurança.',167);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (625,0,'A','O documento é prova de que a dominação holandesa foi muito mais violenta do que a portuguesa.',168);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (626,4,'B','O autor descreve o martírio e os milagres de Uruaçu, estabelecendo esses eventos como testemunho da fé católica e da fidelidade dos mortos à Coroa Portuguesa.',168);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (627,1,'C','O texto de Lopo Curado Garro é um documento de época descrevendo o massacre de Uruaçu, no qual holandeses associados a índios mataram portugueses católicos.',168);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (628,5,'D','Ao enfatizar a ideia de justiça divina e acusar os holandeses e seus associados – os brasilianos – o relato clamava também pela justiça dos homens.',168);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (629,5,'A','O texto apresenta uma crítica ao sistema capitalista baseado no príncipio da contradição conforme encontramos no pensamento de autores como Karl Marx e Pierre-Joseph Proudhon.',169);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (630,0,'B','As observações científicas que aparecem na narrativa são irrelevantes tanto para sua fluidez quanto para se compreender o problema da fome e da miséria no Brasil.',169);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (631,1,'C','O texto expõe de maneira mordaz o modo degradante a que o ser humano pode chegar se não tiver dinheiro no mundo contemporâneo.',169);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (632,4,'D','A argumentação irônica de Jorge Furtado questiona se o ser humano está de fato no topo da escala evolutiva dos animais.',169);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (633,4,'A','Denuncia a presença de politicos corruptos nas eleições brasileiras...',171);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (634,1,'B','Apresenta a imagem de um muro composta por um fragmento de cartaz...',171);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (635,0,'C','Faz referência à sanção e execução da lei da Ficha Limpa...',171);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (636,5,'D','Questiona o sistema eleitoral republicano por suas contradições...',171);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (637,0,'A','O texto é uma descrição da invasão holandesa à Bahia...',172);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (638,4,'B','O padre vê com um olhar negativo os holandeses...',172);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (639,5,'C','A função no Estado português e seu pertencimento à ordem jesuítica...',172);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (640,1,'D','A narrativa do padre Antônio Vieira descreve a violência da chegada...',172);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (641,5,'A','O Poder Moderador garantia, na forma da lei, a possibilidade do despotismo.',173);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (642,1,'B','O Poder Moderador dava ao Imperador o dominio sobre a Assembleia...',173);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (643,4,'C','A instituição do Poder Moderador na Constituição de 1824...',173);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (644,0,'D','Ao Poder Moderador era vetado intervir no Poder Judiciário.',173);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (645,5,'A','Há uma concentração de fortificações na Vila de Nossa Senhora do Desterro...',174);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (646,4,'B','O sistema defensivo da ilha de Santa Catarina tinha o objetivo de consolidar...',174);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (647,0,'C','A presença de fortificações militares como estas dificultou o povoamento...',174);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (648,1,'D','O mapa apresenta um levantamento dos fortes de defesa da Ilha...',174);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (649,0,'A','A letra do samba-enredo é de contestação ao regime politico...',175);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (650,1,'B','A letra do samba-enredo faz alusão ao processo politico que culminou na República...',175);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (651,5,'C','O samba-enredo apropria-se de uma narrativa histórica tradicional...',175);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (652,4,'D','A ideia de liberdade e a igualdade do povo... é recuperada pelo samba...',175);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (653,4,'A','A atividade do tropeirismo ganhou impulso após a descoberta de ouro...',176);
