INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (655,0,'C','As tropas de muares foram substituídas... pelo transporte ferroviário...',176);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (656,1,'D','O tropeirismo era uma atividade econômica que proporcionava a ligação...',176);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (657,1,'A','Expõem que a sobra é o único resultado pertencente ao agricultor...',177);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (658,4,'B','Tratam da questão do sistema de meação...',177);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (659,0,'C','Sugerem que o sistema de meação implica numa exploração inadequada...',177);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (660,5,'D','Discutem o sentido do trabalho no sistema de meação... contrato desigual...',177);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (661,1,'A','A expedição de Martim Afonso de Souza em 1530...',178);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (662,0,'B','Até 1530 os portugueses utilizavam o litoral do Brasil apenas como ponto...',178);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (663,5,'C','O pau-brasil era o principal produto comercializado na costa brasileira...',178);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (664,4,'D','O ano de 1530 marca uma mudança quanto à colonização do Brasil...',178);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (665,5,'A','Faz um jogo entre passado e presente por meio da fala do indígena...',179);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (666,0,'B','O comentário conformista do indigena mostra a docilidade...',179);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (667,1,'C','Faz referência ao contexto da conquista das terras americanas...',179);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (668,4,'D','Apresenta um humor critico ao mostrar os indigenas como já cientes...',179);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (669,4,'A','O luxo trazido pela Familia Real Portuguesa foi utilizado em benefício da politica...',181);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (670,5,'B','O vestuário, ao longo da história, pode funcionar como um espaço de demarcação...',181);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (671,1,'C','Com a abertura dos portos em 1810 e a Queda de Napoleão em 1815...',181);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (672,0,'D','Com a chegada da Familia Real ao Brasil o luxo da monarquia europeia...',181);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (673,5,'A','Acre e Sibéria são entendidos como vazios, isolados e distantes...',182);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (674,4,'B','A anexação da região do Acre ao Brasil foi fruto da assinatura de um acordo...',182);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (675,0,'C','A comparação entre a Sibéria e o Acre faz referência à difícil conquista...',182);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (676,1,'D','A associação construida pela charge entre o Acre e a Sibéria...',182);
