INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (876,4,'D','Como professoras, as mulheres ganhavam a possibilidade de deixar o espaço privado...',236);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (877,1,'A','Na tela, que representa a saída das monções, podemos observar as embarcações...',237);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (878,5,'B','Essa pintura, assim como outras de mesma temática encontradas, por exemplo, no Museu Paulista, compõem uma memória nacional baseada na construção de um passado heroico paulista.',237);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (879,0,'C','As expedições fluviais ocorridas no século XVIII foram menos relevantes que as bandeiras...',237);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (880,4,'D','Nessas viagens que saíam de Porto Feliz e chegavam à Cuiabá, o papel dos indígenas foi fundamental...',237);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (881,0,'A','Era uma milícia dentre tantas formadas no Brasil...',238);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (882,4,'B','Era uma milícia criada para atuar ao lado daqueles que lutavam contra a ocupação holandesa...',238);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (883,1,'C','Caracterizava-se por ser uma milícia composta principalmente por homens negros forros e escravos...',238);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (884,5,'D','Teve como fundador um indivíduo que, por sua influência e capacidade de liderança, recebeu mercês e graças que não eram destinadas aos negros, sendo restritas até mesmo entre os brancos.',238);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (885,5,'A','A crônica rompe com a divisão tradicional existente na história do Brasil ao criar uma ideia de continuidade política entre o Brasil Imperial e a República, sob o título de “Era Bragança”.',239);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (886,1,'B','O autor escreve a crônica no contexto de incertezas e possibilidades que a eleição presidencial de 2002 trazia...',239);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (887,0,'C','Ao se afirmar a possível vitória de um “Silva” sobre um líder “Bragança”, o autor demonstra a crise política...',239);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (888,4,'D','No texto, a noção de “era”, tal como “Era Vargas” e “Era Bragança”, é uma forma de tentar designar um período histórico...',239);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (889,5,'A','Demonstra que logo no primeiro século de colonização da América Portuguesa já havia constantes incursões para o interior do território, o que contradiz a leitura tradicional que se faz do processo colonizador lusitano.',240);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (890,0,'B','Tem por objetivo mapear a região do Rio São Francisco, descrevendo seus aspectos geográficos...',240);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (891,4,'C','Ressalta a necessidade não apenas de investimento para uma expedição de reconhecimento...',240);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (892,1,'D','Mescla informações geográficas do rio e das regiões que o cercam e as possibilidades de exploração de riquezas...',240);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (893,4,'A','Ao comparar imigrantes a escravos, o relato de Davatz pode ser visto como uma contrapropaganda...',241);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (894,0,'B','O texto aponta que, mesmo passando por condições desfavoráveis... era vantajoso para os imigrantes o trabalho nas lavouras paulistas.',241);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (895,5,'C','As memórias apresentadas no texto pelo narrador descrevem, entre outros aspectos, a busca pelo lucro por parte dos empresários e o favorecimento destes pela esfera pública no Brasil.',241);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (896,4,'D','A narrativa do imigrante suíço levanta aspectos relevantes da história imperial brasileira como a criação do sistema de contratos de parceria...',241);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (897,4,'A','Na pintura, observamos características do movimento modernista brasileiro...',243);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (898,1,'B','A pintura associa samba, sensualidade da mulher e natureza.',243);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (899,5,'C','A tela Samba, apesar de sua importância, era propriedade particular...',243);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (900,0,'D','O fato de a tela ter sido destruída no incêndio não é grave, uma vez que a partir dos registros existentes ela pode ser refeita.',243);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (901,5,'A','Há complexas relações entre memória e história, o que indica que os significados dados ao conflito encontram-se ligados a questões políticas de cada época.',244);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (902,4,'B','As representações do conflito Mucker e de sua líder, Jacobina Mentz, foram sendo ressignificadas...',244);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (903,0,'C','Se comparada aos conflitos de Canudos e do Contestado, a Revolta dos Mucker recebeu muito mais atenção...',244);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (904,1,'D','Parte da historiografia, matérias veiculadas na imprensa nos anos 50 e 60... reforçaram o imaginário negativo...',244);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (905,1,'A','No Renascimento ampliou-se o conhecimento cartográfico, a partir da apropriação de textos antigos...',245);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (906,0,'B','As transformações e as especificidades relativas ao ofício de cartógrafo... sugerem o progresso contínuo do pensamento científico, que superou antigas premissas...',245);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (907,4,'C','O desbravamento dos mares entre os séculos XV e XVI foi possível, em parte, pela preservação e estudo do conhecimento marítimo e cósmico...',245);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (908,5,'D','A viagem de Colombo ao Novo Mundo pode ser lida como um grande exemplo da influência dos mapas antigos...',245);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (909,4,'A','Embora se trate de um estudo de história econômica, é possível perceber que o autor traz uma crítica social à instituição da escravidão no período colonial.',246);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (910,5,'B','O argumento central levanta a hipótese de que os engenhos de açúcar se assemelhavam às fábricas do capitalismo...',246);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (911,0,'C','A comparação do engenho à fábrica não se sustenta, pois a produção fabril localiza-se historicamente no meio urbano.',246);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (912,1,'D','O texto demonstra que a montagem dos engenhos de açúcar no início do período colonial não era uma tarefa simples...',246);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (913,0,'A','A pouca adesão de escravos da região de Queimado à insurreição, bem como a traição (abandono) do líder Frei Gregório...',247);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (914,5,'B','O jornal reforça algumas características do Código Criminal de 1830...',247);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (915,1,'C','O jornal caracteriza os negros revoltosos na categoria de criminosos, além de exaltar as iniciativas do governo, responsáveis por reprimir a insurreição e reestabelecer a “tranquilidade” em São José do Queimado.',247);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (916,4,'D','O pároco da igreja mencionada pelo documento, Frei Gregório - conhecido por sua aversão ao sistema escravocrata...',247);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (917,1,'A','O primeiro croqui mostra a Avenida Juscelino Kubitschek e suas imediações, incorporando sugestões de aproveitamento das características naturais do cerrado.',248);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (918,4,'B','Assim como ocorreu com Brasília ou Goiânia, a capital do novo Estado de Tocantins foi projetada a partir de um concurso nacional.',248);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (919,5,'C','A Praça dos Girassóis, localizada no ponto central da cidade, traz diversos elementos que tentam integrar a jovem capital à história nacional...',248);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (920,0,'D','O planejamento da capital trouxe um gradual fim ao caráter agrário do estado de Tocantins, atraindo indústrias a partir de parcerias entre órgãos públicos e privados.',248);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (921,0,'A','O livro ao registrar a culinária brasileira rejeitava os aspectos da culinária estrangeira.',249);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (922,4,'B','A alimentação, que não se restringe à culinária, pode ser encarada como indicador socioeconômico de classes, países e etnias.',249);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (923,4,'C','O Cozinheiro Nacional não se limita a fornecer receitas, mas associa hábitos alimentares e técnicas de preparo a diferentes graus de civilização.',249);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (924,1,'D','O livro de receitas revela aspectos de determinada época e sociedade e indica uma possível familiaridade entre o ofício do cozinheiro...',249);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (925,4,'A','O fato de não se conhecer o autor desta canção indica uma realidade de transmissão de experiências...',250);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (926,0,'B','O uso de expressões que não se valem da norma culta de nossa língua contribui para o atraso cultural...',250);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (927,1,'C','O lirismo da canção une a descrição da natureza do Mato Grosso à realidade social de um dado momento e os sentimentos de saudades daquele que deixou a sua própria terra.',250);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (928,4,'D','Pode-se inferir que o sujeito da canção, ao encontrar “revolução” e “fortes batalhas”, referia-se à Guerra da Tríplice Aliança...',250);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (929,0,'A','Revistas, como a Revista Feminina, e manuais... registraram opiniões consideradas machistas e, por isso, não podem ser utilizados como fontes...',251);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (930,1,'B','Por acentuar características consideradas racionais, o escritório, ambiente doméstico masculino por excelência, funcionava como extensão do universo do trabalho...',251);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (931,4,'C','Alguns elementos da fotografia reforçam o texto, tais como as estantes de livros; a mesa ampla e cheia de afazeres; a presença de um homem, Amadeu Amaral, trajando terno e gravata, em uma posição sóbria e intelectual.',251);
