INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (1401,4,'A','Pedro Weingärtner é um artista nascido no Rio Grande do Sul, descendente de alemães, que fez sua formação e parte de sua carreira na Europa. No início do século XX, sua obra ganhou destaque em exposições nacionais e internacionais.',381);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (1402,1,'B','Representa uma cena cotidiana de carreteiros gaúchos, onde é possível ver homens sentados em roda, tomando chimarrão, próximos a uma fogueira e rodeados por animais e paisagem regional.',381);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (1403,5,'C','Faz parte do conjunto de obras que corroboram para a construção de determinada identidade visual do nativo do Rio Grande do Sul, processo que se iniciou na elaboração da imagem do gaúcho.',381);
