INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (1405,5,'A','O diálogo, enquanto gênero textual, remonta à antiguidade clássica e a filósofos como Platão, assinalando preocupações pedagógicas.',382);
