INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2733,5,'A','A violência das campanhas militares no nordeste sofreu apagamento na medida em que certas correntes historiográficas priorizaram o papel político das elites paulistas e seu discurso de em torno da unidade e harmonia do novo país.',759);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2734,1,'B','As batalhas relacionadas à Independência do Brasil mobilizaram civis com pouca instrução militar e armamentos improvisados.',759);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2735,4,'C','Os eventos locais de resistência ao longo do processo de Independência brasileira foram importantes na definição de memórias, símbolos e valores regionais.',759);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2736,0,'D','Os portugueses conseguiram efetivar o plan de manter uma colônia ao norte do Brasil até que o recém-instaurado governo imperial de Dom Pedro I firmou o Tratado de Paz, Amizade e Aliança de 1825.',759);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2737,0,'A','A necessidade de descartar objetos mais cotidianos e preservar aqueles que são únicos, como forma de valorizar o ensino de história e os museus.',760);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2738,4,'B','A desaparição de objetos, mas também a sua relevância, quando podem ultrapassar a existência de seus proprietários e a sua utilidade original.',760);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2739,5,'C','A possibilidade de entender e ensinar a história por meio do estudo da cultura material e dos objetos como vestígios do passado.',760);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2740,1,'D','A importância dos objetos nas vivências humanas e as formas pelas quais pessoas e sociedades se relacionam com eles.',760);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2741,1,'A','são um exemplo da globalização da cultura, pois são produções japonesas que passaram a ser parte do cotidiano infanto juvenil.',761);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2742,0,'B','Ganharam espaço na televisão aberta brasileira por uma razão identitária, buscando a representatividade nipônica.',761);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2743,4,'C','impulsionaram a popularização de mangás, que desde os anos 1950 já circulavam entre comunidades de descendentes de japoneses.',761);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2744,5,'D','popularizaram-se na década de 1990 e compõem culturas juvenis, constituindo um significativo ramo no mercado editorial, de brinquedos e jogos eletrônicos.',761);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2745,5,'A','servem como evidência para embasar ou contradizer narrativas sobre o passado, independentemente de serem oficiais ou pessoais.',762);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2746,4,'B','são geridos de acordo com a Lei No 8.159, de 1991 (Lei dos Arquivos), que define uma política nacional para lidar com arquivos públicos e privados.',762);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2747,1,'C','foram muitas vezes salvos do descarte não por sua importância em si, mas pela importância adquirida pelo personagem a que se referem.',762);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2748,0,'D','estão sob a proteção dessas instituições, mesmo quando pertenceram a pessoas comuns cujas vidas não tiveram importância histórica.',762);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2749,4,'A','A proposta publicitária faz referência ao período de maior supressão de diretos durante a Ditadura Civil-Militar, marcado pela assinatura do AI-5.',763);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2750,5,'B','A campanha, ao apresentar o produto, traz um discurso textual e imagético que naturaliza a tortura e, de certa forma, a torna positiva.',763);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2751,1,'C','As propagandas, veiculadas em 1969, trazem textos, a imagem do produto a ser consumido - o aparelho de televisão Philips 550 ao lado de um chicote de corda.',763);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2752,0,'D','As publicações como as apresentadas não dialogavam com a imprensa da época, que se posicionava contra da ditadura, a exemplo do Jornal do Brasil.',763);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2753,1,'A','inferir que o problema de discriminação racial e étnica em Portugal atinge também outras nacionalidades.',764);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2754,4,'B','observar o crescimento da imigração brasileira para Portugal e o aumento das denúncias de episódios de xenofobia.',764);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2755,5,'C','atestar as relações conflituosas entre povos que colonizaram e povos que foram colonizados.',764);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2756,0,'D','condenar a desagregação social gerada pelas migrações das antigas colônias para a Europa.',764);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2757,0,'A','Aborda a história não-oficial do Rio Grande do Sul, oferecendo uma visão crítica sobre sujeitos históricos marginalizados.',765);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2758,1,'B','Apresenta elementos culturais alusivos a um tipo regional, com sua história, crenças, modo de se vestir e de se comportar.',765);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2759,4,'C','Foi publicado em uma revista de ampla circulação nacional e escrito por um dos principais expoentes do tradicionalismo gaúcho.',765);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2760,5,'D','Formula uma identidade para o gaúcho, afirmando suas qualidades e valores morais, em que a masculinidade se sobressai.',765);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2761,1,'A','“Onde o povo segue celebrando / O Sol, a Lua e tudo que é profano” faz uma menção aos aspectos espirituais do Caminho, importantes para povos indígenas, como os Guaranis.',766);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2762,5,'B','“Onde reina e manda qualquer um / Onde o rei pode ser um fora da lei” sintetiza uma crítica à exploração colonial e aos problemas socioambientais atuais da região cortada pelo Caminho.',766);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2763,4,'C','“No tango, charango, viola e chamamé” constitui referência musical à extensão territorial e à natureza transnacional que se relaciona ao Peabiru.',766);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2764,0,'D','“Na promessa de um Eldorado / Vinham almas aventureiras” homenageia o caráter civilizador das iniciativas de interiorização dos exploradores europeus que utilizaram o Peabiru.',766);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2765,5,'A','contribuíram para a consolidação de uma historiografia profissional no Brasil, com abordagens e métodos distintos daqueles da tradição ensaística dos anos 1930 e 1940.',767);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2766,4,'B','são determinados por uma combinação específica e distinta de referências científicas, práticas sociais, identidades políticas, valores culturais e formas de escrita.',767);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2767,0,'C','foram superados pois generalizam o local a partir do total, o que inviabiliza a produção historiográfica e impossibilita o encontro de indícios fomentadores dessas narrativas.',767);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2768,1,'D','divergem, entre outros pontos, sobre a emancipação comercial da colônia em relação à metrópole e ao papel das estruturas locais de economia e poder.',767);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2769,5,'A','destaca a persistência de um saber indígena que hoje é resguardado pelas tacacazeiras – estas que tiveram o seu ofício reconhecido como patrimônio cultural imaterial do município de Belém.',768);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2770,0,'B','propõe a superação dos regionalismos ao eleger a mandioca como elemento centralizador da nacionalidade e os indígenas como unificadores dos costumes alimentares do Brasil.',768);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2771,1,'C','explica brevemente o que são os alimentos líquidos e, em seguida, oferece o exemplo de uma sopa denominada mani poi que, por sua vez, deu origem aos atuais tacacás.',768);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2772,4,'D','utiliza observações escritas de viajantes europeus – tais como as de autoria de Abbeville –, a fim de historicizar determinados elementos e práticas relacionados à alimentação no Brasil.',768);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2773,0,'A','No quadro de Brocos, a matriarca da família é retratada orando de pé. A escolha da postura revela uma reverência do pintor à estrutura hierárquica baseada na idade e na experiência, prática tipicamente cristã.',769);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2774,5,'B','Na aquarela de Sguilla, é feita uma contranarrativa do quadro original. A artista se utiliza da cultura visual para construir uma crítica antirracista a partir da relação entre as imagens.',769);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2775,4,'C','No segundo documento, a matriarca da família desce um olhar afetuoso para seu neto. O semblante da senhora constitui uma ruptura com os muitos retratos trágicos e violentos feitos de negros pela arte oitocentista.',769);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2776,1,'D','No primeiro documento, há uma gradação intencional na cor da pele dos retratados. Essa proposta tinha como objetivo reiterar aspectos discriminatórios da ideologia de embranquecimento da nação.',769);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2777,5,'A','aponta o nomadismo como um dos elementos que explicam a heterogeneidade e a constituição de regras e culturas próprias a cada grupo de artistas.',771);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2778,4,'B','estabelece a necessidade de utilização de métodos de pesquisa histórica, como entrevistas e leitura de bibliografia diversa, para construir uma história do circo no Brasil.',771);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2779,0,'C','mostra como para os artistas circenses as origens de seus antepassados europeus têm mais peso que o pertencer a um determinado grupo.',771);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2780,1,'D','apresenta o deslocamento dos artistas circenses para o Brasil a partir do século XVIII, tendo como causas guerras, perseguições e proibições de exercerem seu trabalho em seus países de origem.',771);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2781,4,'A','coexistem com os sinos dos campanários das igrejas, na transição da paisagem sonora das cidades no mundo industrializado.',772);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2782,0,'B','distribuem o som disciplinar, uma vez que estão alocadas de maneira homogênea nos ambientes urbanizados, independentes da segregação sócio-espacial.',772);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2783,1,'C','participam da rotina social, uma vez que servem como delimitadores das práticas cotidianas de várias gerações, provocando diferentes reações nos habitantes.',772);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2784,5,'D','constituem um marco sonoro, que promove um senso de identidade comunitária, funcionando como uma referência temporal na esfera urbana.',772);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2785,4,'A','“Não há mulher desprezada, / galã desfavorecido, / que deixe de ir ao quilombo / dançar o seu bocadinho” tratam da popularidade desses cultos entre pessoas de diferentes etnias e posições sociais.',773);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2786,0,'B','“O que sei, é, que em tais danças / Satanás anda metido, / e que só tal padre-mestre / pode ensinar tais delírios” demonstram que o autor entendia que os cultos eram perigosos para a moral, por envolverem danças proibidas pela Igreja na época.',773);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2787,5,'C','“E quando vão confessar-se, / encobrem aos Padres isto, / porque o têm por passatempo, / por costume, ou por estilo” criticam a hipocrisia dos cristãos que frequentam cultos proibidos e nem ao menos se confessam ou arrependem.',773);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2788,1,'D','“Que de quilombos que tenho / com mestres superlativos, / nos quais se ensinam de noite / os calundus, e feitiços” explicitam que o poema tratará das cerimônias religiosas afro-brasileiras.',773);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2789,0,'A','Atestam a relevância do panamericanismo nos anos de 1960 e 1970 e a influência da música norte-americana para o desenvolvimento do reggae no Maranhão.',774);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2790,5,'B','Exemplificam como a forte conexão entre local e global afeta práticas sociais e comportamentais em diferentes países americanos.',774);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2791,1,'C','Demonstram o desenvolvimento do reggae como manifestação cultural maranhense, abordando questões como pobreza, discriminação, desigualdade social e econômica.',774);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2792,4,'D','Indicam a importância das trocas de tecnologias e referências culturais para o desenvolvimento das radiolas e do reggae como cultura popular.',774);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2793,1,'A','apresenta aparelhos eletrônicos para uso pessoal com destaque para a inovação tecnológica e a facilidade de uso que eles representam.',775);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2794,4,'B','traz, além da imagem do produto, informações técnicas, alerta sobre a pirataria e a lista de revendedores autorizados.',775);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2795,5,'C','usa como apelo publicitário a possibilidade de se enviar mensagens secretas, uma forma de conquistar o público jovem.',775);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2796,0,'D','oferece poucas informações sobre os usos do produto como forma de instigar a curiosidade dos possíveis possuidores.',775);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2797,5,'A','A percepção de uma constituição do Brasil baseada na convivência harmônica das três raças presente em quadrinhos da Turma da Mônica afirma a persistência dessa ideia.',776);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2798,1,'B','O objetivo do trecho em destaque é ilustrar a formação sociocultural brasileira, retratando-a como um processo espontâneo e natural.',776);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2799,4,'C','A miscigenação entre os povos indígenas, negros e brancos foi explorada na literatura brasileira por meio de obras como “Macunaíma” (1928).',776);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2800,0,'D','A veiculação de conteúdos vinculados ao folclore brasileiro por meio de histórias em quadrinhos ilustra a obsolescência da tradição oral em reproduzir histórias populares.',776);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2801,0,'A','Diferente de outras músicas do cantor, ”Que país é este” é utilizada por grupos de extrema direita por não apresentar qualquer crítica à violência sofrida por determinadas minorias.',777);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2802,1,'B','O conteúdo informa sobre uma notificação extrajudicial movida pelo herdeiro do patrimônio de Renato Russo direcionada a uma companhia de tecnologia.',777);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2803,5,'C','O caso evidencia as disputas em torno de uma obra artística, revelando que os seus sentidos podem ser ressignificados a depender do contexto histórico e político.',777);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2804,4,'D','Renato Russo foi compositor de músicas como Veraneio Vascaína (1986), que é uma crítica à polícia, e Perfeição (1993), que ironiza o patriotismo.',777);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2805,1,'A','A fotografia, ambientada na entrada do colégio Des Oiseaux, é composta majoritariamente por crianças, além de uma freira e de um homem adulto que dirige uma carruagem.',778);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2806,5,'B','Matricular as crianças em um estabelecimento de ensino como o Des Oiseaux implicava uma dupla operação: de agregação, entre as famílias do mesmo estrato social, e de segregação social.',778);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2807,0,'C','Além do Des Oiseaux, as Irmãs de N. Sra. Das Cônegas de S. Agostinho também administraram instituições masculinas, utilizando o mesmo currículo escolar para meninos e meninas.',778);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2808,4,'D','O colégio Des Oiseaux, localizado no bairro da Consolação, em São Paulo, foi uma instituição de ensino religiosa voltada, especialmente, às filhas da elite paulistana.',778);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2809,5,'A','Demonstram o carácter eugenista dos estudos médicos a respeito das colônias alemãs no Brasil e seu estado de germanidade.',779);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2810,4,'B','Apresentam estudos germânicos sobre medicina tropical, campo dedicado ao estudo das patologias consideradas típicas dos países do hemisfério sul.',779);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2811,1,'C','Tratam da presença de colonos alemães no Espírito Santo no início do século XX, sua adaptação e relação com a população nativa, sobretudo de origem africana.',779);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2812,0,'D','Atestam como não houve colaboração de médicos brasileiros na pesquisa conduzida pelos alemães em território espírito-santense.',779);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2813,4,'A','demonstra uma arte e uma técnica em extinção produzidas a partir de fotografias analógicas.',780);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2814,0,'B','evidencia a utilização dos retratos pigmentados produzidos pelo artista como ex-voto pelos clientes após a morte de um ente familiar.',780);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2815,5,'C','permite refletir sobre as imagens geradas por Inteligência Artificial atualmente em oposição às habilidades e à sensibilidade humanas.',780);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2816,1,'D','exibe o trabalho do retratista cearense Júlio Santos, que produz imagens a partir do retoque e da fotopintura.',780);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2817,5,'A','A polêmica entre “vencedores e vencidos” pela posse do canhão reflete uma disputa pela memória da Guerra da Tríplice Aliança e pela responsabilidade sobre a destruição que ela levou ao Paraguai.',781);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2818,4,'B','Argumentos semelhantes aos encontrados para a recusa da devolução, como o da “incapacidade de cuidar dos próprios bens”, têm sido usados por países europeus contra países do sul global.',781);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2819,0,'C','A devolução do artefato implicaria danos ao patrimônio cultural brasileiro, uma vez que o bem foi tombado pelo IPHAN e não existe a possibilidade de destombamento.',781);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2820,1,'D','Retrata-se a negociação pela devolução de um artefato que, fabricado no Paraguai e levado como butim de guerra, encontra-se hoje museificado no Brasil.',781);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2821,0,'A','Intitulada “Halloween”, a charge apresenta três fantasias assustadoras, sendo uma delas a de “Fake News”, caracterizada pelo nariz longo somado às logomarcas de redes sociais.',785);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2822,0,'B','Ao identificar a fantasia de “Fake News” como sendo de um monstro, a charge realça o papel nocivo da divulgação de informações falsas, o que pode implicar na violação de direitos.',785);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2823,0,'C','Há, no Brasil, o Projeto de Lei 2630/2020, cujo objetivo é estabelecer regras para o combate à desinformação nas redes sociais e serviços de mensagens privadas.',785);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2824,0,'D','Características do tempo presente, as chamadas “Fake News” são manifestações que garantem a liberdade de expressão em redes sociais.',785);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2825,0,'A','Questiona a perspectiva eurocêntrica de um jesuíta português, Simão de Vasconcelos, que foi um dos poucos sobreviventes da tragédia narrada.',786);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2826,0,'B','Apresenta um episódio protagonizado por D. Pedro F. Sardinha que, antes de assumir o alto cargo como bispo do Brasil, foi vigário-geral em outro domínio português.',786);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2827,0,'C','Narra o ocorrido com uma tripulação, desde o naufrágio da nau até a morte de alguns de seus membros pelos caetés.',786);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2828,0,'D','Acentua as dificuldades da colonização e, concomitantemente, oferece argumentos para justificar a intensificação da dominação portuguesa.',786);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2829,0,'A','A Casa de Correção da Corte foi a primeira penitenciária instalada no Brasil, e o uso da fotografia revela uma estratégia de controle sobre os apenados.',787);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2830,0,'B','Os autores das imagens eram os “Photographos da Casa Imperial”, título concedido a partir do ano de 1851 aos profissionais que atuavam para o império.',787);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2831,0,'C','A prisão perpétua vigorou no Brasil com o Código Criminal de 1830, mas os presos podiam receber o perdão da pena, conferido pelo imperador.',787);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2832,0,'D','Os registros fazem parte de um álbum que traz fichas de condenados, constando seus retratos e um resumo das suas penas, enquanto o relatório informa sobre uma câmera fotográfica.',787);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2833,0,'A','Foi publicado no jornal independente Lampião da Esquina, veículo de comunicação pertencente à comunidade homossexual.',788);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2834,0,'B','Evidencia que a violência empregada pelo regime militar brasileiro não era apenas contra os opositores políticos.',788);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2835,0,'C','Reconhece a importância della resolução da Anistia Internacional, mas é descrente quanto aos seus impactos no Brasil.',788);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2836,0,'D','Explica os limites da aplicação da resolução no Brasil, ainda que a abertura política ampliasse os direitos da população LGBTQIAPN+.',788);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2837,0,'A','interpretada nos anos 1970 pelo grupo Novos Baianos, foi censurada pela Polícia Federal, uma vez que comprometia relações diplomáticas entre Brasil e Estados Unidos.',789);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2838,0,'B','composta por Assis Valente, exalta elementos culturais e identitários do Brasil, especialmente da Bahia, como a comida, a dança, a religiosidade e a música.',789);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2839,0,'C','finalizada em 1940, pode ser compreendida à luz da Política da Boa Vizinhança, apresentando o Brasil de forma positiva aos estrangeiros.',789);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2840,0,'D','apresentada pelo compositor a Carmen Miranda, acabou sendo rejeitada pela intérprete, que se sentiu desconfortável em cantar seus versos.',789);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2841,0,'A','associam o cuidado estético aos princípios da higiene e da civilidade que se popularizaram no Brasil durante a Primeira República.',790);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2842,0,'B','reforçam uma idealização de beleza masculina representada pela fartura e lisura dos cabelos, pele branca e jovialidade.',790);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2843,0,'C','demonstram que as questões capilares, como a calvície, eram uma preocupação estética para os homens na década de 1930.',790);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2844,0,'D','evidenciam o uso popular de produtos cosméticos, fenômeno impulsionado pela regulamentação da profissão de barbeiro em 1932.',790);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2845,0,'A','Ao longo do século XX, o jogo do bicho no Rio de Janeiro se organizou em torno de algumas famílias que atuavam de forma análoga àquelas da máfia, especialmente a italiana.',791);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2846,0,'B','Levar a população a frequentar parques, jardins botânicos e zoológicos como o de Vila Isabel fazia parte de ideais civilizatórios e modernizantes aos quais a recém instaurada república aspirava.',791);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2847,0,'C','A nova forma de loteria se espalhou e caiu no gosto popular convergindo com a busca por controle social e de casas e práticas de jogatinas que a administração pública buscava coibir.',791);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2848,0,'D','O Jogo do Bicho, que movimenta milhões de apostas pelo Brasil, passou a fazer parte do imaginário popular sob a impressão de ser acessível ou inofensivo, apesar da ilegalidade e da criminalidade que o cercam.',791);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2849,0,'A','A estreia de uma mulher “advogado” no tribunal do júri mereceu um artigo ilustrado de capa, num jornal de expressiva circulação.',792);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2850,0,'B','O Instituto dos Advogados do Brasil não reconheceu o direito de Maria Coelho exercer a profissão, mas reconheceu o de Myrthes de Campos, formada no exterior.',792);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2851,0,'C','Delmira Secundina da Costa e Maria Fragoso da Silva também concluíram, em 1888, o curso na Faculdade de Direito do Recife.',792);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2852,0,'D','A presença feminina em espaços tradicionalmente masculinos foi compreendida por parte da imprensa oitocentista como indicativa de avanço do movimento feminista.',792);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2853,0,'A','O atentado do Riocentro foi um ataque orquestrado pelo Exército e pela Polícia Militar, como estratégia para atrasar a abertura política em andamento.',793);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2854,0,'B','Casagrande se exilou na Itália em 1983 devido à ameaça de prisão por ter usado a camisa da Democracia Corinthiana na final do campeonato paulista.',793);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2855,0,'C','Os jogadores do Corinthians que participavam do movimento entendiam a relevância de seus lugares para veicular uma mensagem política para as grandes massas.',793);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2856,0,'D','A Democracia Corinthiana foi um movimento encabeçado por dirigentes e jogadores do Corinthians em favor da democracia dentro e fora do clube.',793);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2857,0,'A','Indicam a preocupação com a instrução da raça negra em Santa Catarina a fim de cumprir a Lei Afonso Arinos que pune a discriminação no Brasil.',794);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2858,0,'B','Demonstram a força do movimento negro que, desde os anos 1920, se reunia em associações em diferentes partes do Brasil, como o Centro Cívico e Recreativo José Boiteux, em Florianópolis, e o Grêmio Recreativo Flor de Maio.',794);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2859,0,'C','Evidenciam o surgimento da União Negra Catarinense em Florianópolis e a importância do jornal Vanguarda para a divulgação e visibilidade do movimento.',794);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2860,0,'D','Ocupam um espaço na imprensa catarinense da década de 1930 e abordam questões de interesse de afrodescendentes como a luta de classes e contra o preconceito racial.',794);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2861,0,'A','A peça publicitária faz parte de uma campanha sobre capacitismo realizada em referência ao Dia Internacional da Pessoa com Deficiência.',796);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2862,0,'B','A Lei N 13.146/2015 instituiu o Estatuto da Pessoa com Deficiência com objetivo de garantir a essas pessoas condições de igualdade no exercício da cidadania.',796);
INSERT INTO `SKYNET_item` (`id_item`, `pontuacao`, `identificador`, `texto`, `id_questao_id`) VALUES (2863,0,'C','A categorização e exclusão de pessoas com deficiência veio de uma prática eugenista adotada pelo Estado brasileiro que culminou na criação das paraolimpíadas.',796);
